INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(1, 'radical', 'ground', '一', 'This radical consists of a single, horizontal stroke. What''s the biggest, single, horizontal stroke? That''s the <radical>ground</radical>. Look at the ground, look at this radical, now look at the ground again. Kind of the same, right?', 'https://api.wanikani.com/v2/subjects/1', 'https://www.wanikani.com/radicals/ground', 1, 2, '2012-02-27T18:08:16Z', NULL, '2026-04-04T20:17:45.612577Z'),
(2, 'radical', 'fins', 'ハ', 'These look like <radical>fins</radical>. What''s a pair of disembodied fins doing here?! Some fish must have left them here by accident. Bet they''re really missing these fins right about now.', 'https://api.wanikani.com/v2/subjects/2', 'https://www.wanikani.com/radicals/fins', 1, 2, '2012-02-27T18:11:07Z', NULL, '2026-03-23T02:54:10.694388Z'),
(3, 'radical', 'drop', '丶', 'This little radical is a <radical>drop</radical>, maybe of water or some other liquid. Notice how it''s only one drop? Sometimes radicals and kanji will have more than one drop in them, but don''t let that throw you off.', 'https://api.wanikani.com/v2/subjects/3', 'https://www.wanikani.com/radicals/drop', 1, 2, '2012-02-27T18:12:15Z', NULL, '2026-02-04T07:18:03.59291Z'),
(4, 'radical', 'seven', '七', 'What does this radical look like? Hmm, nothing much. What about if you turn it upside down? Now does it look like a 7 with a line through it? Close enough to help you to remember that this radical is <radical>seven</radical>, right? Just remember, when you see this radical, flip it over and see what number it looks like. If you can do that, you can remember the meaning!', 'https://api.wanikani.com/v2/subjects/4', 'https://www.wanikani.com/radicals/seven', 1, 2, '2012-02-27T18:13:40Z', NULL, '2026-01-30T23:35:23.672471Z'),
(5, 'radical', 'slide', '丿', 'Close your eyes and imagine you''re a kid again. Now open them and... look! It''s a <radical>slide</radical>! Imagine little you sliding down this slide over and over, having a great time. Imagination + emotion makes for good memorization!', 'https://api.wanikani.com/v2/subjects/5', 'https://www.wanikani.com/radicals/slide', 1, 2, '2012-02-27T18:14:26Z', NULL, '2026-02-27T03:26:37.001449Z'),
(6, 'radical', 'barb', '亅', 'This radical is shaped like a <radical>barb</radical>. Kind of like the barb you''d see on a barbed fishing hook. Imagine that thing getting stuck in your arm or something. Not exactly pleasant. Say out loud, "Oh dang, I got a barb stuck in me!" Alright, relax, it''s only a little barb.', 'https://api.wanikani.com/v2/subjects/6', 'https://www.wanikani.com/radicals/barb', 1, 2, '2012-02-27T18:15:18Z', NULL, '2026-02-04T19:24:51.658554Z'),
(7, 'radical', 'two', '二', 'One line plus another line equals <radical>two</radical> lines. This radical represents the number two. Pretty simple, right? Can you guess what three looks like? I bet you can...', 'https://api.wanikani.com/v2/subjects/7', 'https://www.wanikani.com/radicals/two', 1, 2, '2012-02-27T18:16:05Z', NULL, '2026-04-08T06:30:43.680591Z'),
(8, 'radical', 'lid', '亠', 'This looks like something you''d put on a kettle or a pot, right? It even has a little handle to make sure you don''t burn yourself. This is some kind of <radical>lid</radical>.', 'https://api.wanikani.com/v2/subjects/8', 'https://www.wanikani.com/radicals/lid', 1, 2, '2012-02-27T18:16:26Z', NULL, '2026-01-16T18:51:44.236861Z'),
(9, 'radical', 'person', '人', 'This is a <radical>person</radical>. They''re standing with their arms down at their sides and their legs spread out, which kind of makes them look like a torso with a pair of legs. Think of 人 as highlighting the bipedal nature of people. Walking on two legs? Probably a person.', 'https://api.wanikani.com/v2/subjects/9', 'https://www.wanikani.com/radicals/person', 1, 2, '2012-02-27T18:17:34Z', NULL, '2026-04-08T06:30:43.680591Z'),
(10, 'radical', 'toe', 'ト', 'This radical kind of looks like a <radical>toe</radical>. See the one weird toe coming off the side of it? This also looks like the katakana character ト (to), which sounds like the word "toe." So whenever you see ト, just think toe.', 'https://api.wanikani.com/v2/subjects/10', 'https://www.wanikani.com/radicals/toe', 1, 2, '2012-02-27T18:19:09Z', NULL, '2026-03-31T18:20:46.600461Z'),
(11, 'radical', 'nine', '九', 'If you look at this radical in just the right way, you''ll notice that it kind of looks like the letters "n" and "i" (the "i" comes from the little flippy-up stroke on the right side). What do the letters "n" and "i" start spelling? Why, the word <radical>nine</radical>.', 'https://api.wanikani.com/v2/subjects/11', 'https://www.wanikani.com/radicals/nine', 1, 2, '2012-02-27T18:20:08Z', NULL, '2026-01-12T15:28:07.250648Z'),
(12, 'radical', 'enter', '入', 'Watch out! This isn''t the person radical, it''s something else. What''s the difference? The right side is longer than the left. This radical also has that extra part sticking out at the top. See it? It kind of looks like a person lowering their head to go inside a tent or something. That''s why this radical is <radical>enter</radical>.', 'https://api.wanikani.com/v2/subjects/12', 'https://www.wanikani.com/radicals/enter', 1, 2, '2012-02-27T18:24:26Z', NULL, '2025-10-01T06:09:46.379353Z'),
(13, 'radical', 'power', '力', 'Imagine a guy flexing his arm downward to show off his steroid-pumped arm. It''s huge. It''s so full of <radical>power</radical>. RARRRWWWRRR!!', 'https://api.wanikani.com/v2/subjects/13', 'https://www.wanikani.com/radicals/power', 1, 2, '2012-02-27T18:39:24Z', NULL, '2026-02-16T09:49:50.723034Z'),
(14, 'radical', 'prison', '勹', 'This looks like an enclosure of sorts — that''s why it''s a <radical>prison</radical>. Imagine a tiny prisoner curled up inside, staring off into space, completely convinced they''re trapped forever. Ironically this prison is actually wide open. They''re just so consumed with self-pity that they haven''t realized they''ve been free to leave all along.', 'https://api.wanikani.com/v2/subjects/14', 'https://www.wanikani.com/radicals/prison', 1, 2, '2012-02-27T18:40:12Z', NULL, '2026-03-23T17:20:01.534933Z'),
(15, 'radical', 'cross', '十', 'This radical looks like a <radical>cross</radical>. I mean, just look at it. Two bars going through each other = a cross!', 'https://api.wanikani.com/v2/subjects/15', 'https://www.wanikani.com/radicals/cross', 1, 2, '2012-02-27T18:40:49Z', NULL, '2026-04-06T17:30:52.824393Z'),
(16, 'radical', 'mouth', '口', 'A big, gaping, square hole represents someone opening their giant <radical>mouth</radical> to tell you something stupid.', 'https://api.wanikani.com/v2/subjects/16', 'https://www.wanikani.com/radicals/mouth', 1, 2, '2012-02-27T18:41:46Z', NULL, '2026-04-01T09:46:52.810583Z'),
(18, 'radical', 'big', '大', 'This radical looks just like a stick figure—more specifically, a really <radical>big</radical> guy with his arms stretched out nice and big. When you see this radical, just think big, because this guy is really BIG!', 'https://api.wanikani.com/v2/subjects/18', 'https://www.wanikani.com/radicals/big', 1, 2, '2012-02-27T18:43:11Z', NULL, '2026-02-26T05:44:30.75481Z'),
(19, 'radical', 'woman', '女', 'This radical looks like a curtsying <radical>woman</radical>. Another way to think of it could be as two stacked Xs, since women generally have XX chromosomes. That''s why this is the woman radical. ', 'https://api.wanikani.com/v2/subjects/19', 'https://www.wanikani.com/radicals/woman', 1, 2, '2012-02-27T18:43:53Z', NULL, '2026-03-30T10:30:14.672685Z'),
(20, 'radical', 'mountain', '山', 'This is a <radical>mountain</radical>. See the big peak in the middle and the smaller ones on either side? This totally looks like a mountain.', 'https://api.wanikani.com/v2/subjects/20', 'https://www.wanikani.com/radicals/mountain', 1, 2, '2012-02-27T18:44:33Z', NULL, '2025-12-10T21:18:14.999229Z'),
(21, 'radical', 'river', '川', 'This radical already looks like a <radical>river</radical>. See how the lines represent the flow of the river? There''s even a slight bend in this river. So when you see this radical, you should think "river."', 'https://api.wanikani.com/v2/subjects/21', 'https://www.wanikani.com/radicals/river', 1, 2, '2012-02-27T18:45:14Z', NULL, '2025-12-31T22:20:13.293925Z'),
(22, 'radical', 'sun', '日', 'Since there are no circles in Japanese characters, sometimes rectangles or squares have to make do. In this case, this big rectangle is the <radical>sun</radical>. The middle line is a cloud, moving across the sun. Picture it, but don''t actually look at the sun and burn your eyes!', 'https://api.wanikani.com/v2/subjects/22', 'https://www.wanikani.com/radicals/sun', 1, 2, '2012-02-27T18:45:52Z', NULL, '2026-04-09T00:43:29.897949Z'),
(23, 'radical', 'tree', '木', 'Do you see the <radical>tree</radical> in here? It has branches, and then it has the foliage coming down diagonally from it, spreading out like a tree would. That''s why this radical is a tree.', 'https://api.wanikani.com/v2/subjects/23', 'https://www.wanikani.com/radicals/tree', 1, 2, '2012-02-27T18:46:18Z', NULL, '2026-03-29T18:10:47.677773Z'),
(25, 'radical', 'construction', '工', 'You know those big steel girders that are used for the frame of big buildings? This is like the end of one of those, and has a very distinct shape, just like this radical. These girders are used in construction, which is why this radical means <radical>construction</radical>. Funny thing is, you use these girders to put together buildings just like you''re going to use this radical to put together kanji!', 'https://api.wanikani.com/v2/subjects/25', 'https://www.wanikani.com/radicals/construction', 1, 2, '2012-02-28T20:27:19Z', NULL, '2025-12-03T19:34:09.930091Z'),
(8761, 'radical', 'stick', '丨', 'This is a <radical>stick</radical>, sticking straight up. It even looks like a stick.', 'https://api.wanikani.com/v2/subjects/8761', 'https://www.wanikani.com/radicals/stick', 1, 2, '2012-02-27T18:34:03Z', NULL, '2025-11-07T23:35:45.556698Z'),
(8762, 'radical', 'gun', '𠂉', 'This looks a lot like a <radical>gun</radical> pointing to the right. You have a handle on the left, and the barrel pointing to the right. Imagine it hanging in a case on the wall in a museum.', 'https://api.wanikani.com/v2/subjects/8762', 'https://www.wanikani.com/radicals/gun', 1, 2, '2012-02-27T18:34:58Z', NULL, '2025-11-27T18:56:52.200313Z'),
(17, 'radical', 'dirt', '土', 'At first this looks like a cross in the ground, but it''s actually something growing in the <radical>dirt</radical>. It''s a little sprout, already rocking three leaves. And it''s all thanks to that dirt! When you see this radical, think about how amazing it is that things just, like, grow in the dirt.', 'https://api.wanikani.com/v2/subjects/17', 'https://www.wanikani.com/radicals/dirt', 2, 2, '2012-02-27T18:42:45Z', NULL, '2026-04-08T07:13:50.388752Z'),
(24, 'radical', 'sword', '刀', 'This is the <radical>sword</radical> radical. The ノ part is the curvy sword, while the rest is a samurai bowing deeply, like 90 degrees, as he holds that sword — probably before a sword fight. By the way, don''t confuse this with the power radical (力). See the difference? In the sword radical (刀), the ノ doesn''t pierce through the bowing samurai. (Lucky for him.)', 'https://api.wanikani.com/v2/subjects/24', 'https://www.wanikani.com/radicals/sword', 2, 2, '2012-02-28T20:26:43Z', NULL, '2026-02-26T05:44:30.75481Z'),
(26, 'radical', 'narwhal', 'ナ', 'This radical looks like a <radical>narwhal</radical>. See the tail at the bottom, and the majestic narwhal horn poking out at the top? It also looks like the katakana character ナ (na), so you can remember it that way too. Na-na-na-narwhal! Just be careful not to confuse this with the treasure radical (メ). The sideways line for that one is at more of a downward angle, like an "X." But the sideways line for narwhal is horizontal (ナ).', 'https://api.wanikani.com/v2/subjects/26', 'https://www.wanikani.com/radicals/narwhal', 2, 2, '2012-02-28T21:02:20Z', NULL, '2025-10-01T06:09:46.503712Z'),
(27, 'radical', 'street', '丁', 'Imagine viewing this one from above — looks like a couple of streets, right? Maybe a three-way intersection at the top there? Well, that''s why this is the radical for <radical>street</radical>.', 'https://api.wanikani.com/v2/subjects/27', 'https://www.wanikani.com/radicals/street', 2, 2, '2012-02-28T21:03:25Z', NULL, '2026-04-06T19:56:31.688597Z'),
(28, 'radical', 'legs', '儿', 'This radical already looks like a pair of <radical>legs</radical>. There''s even feet on these legs. That''s how you know these are legs and not fins (or something else).', 'https://api.wanikani.com/v2/subjects/28', 'https://www.wanikani.com/radicals/legs', 2, 2, '2012-02-28T21:04:44Z', NULL, '2026-01-30T23:27:12.714404Z'),
(29, 'radical', 'head', '冂', 'This is the outline of a <radical>head</radical>. A really square head, admittedly, but try to imagine it facing to the right. The left side is the back of the head, and the barb-like part on the right shows the curve of the chin. See the head?', 'https://api.wanikani.com/v2/subjects/29', 'https://www.wanikani.com/radicals/head', 2, 2, '2012-02-28T21:05:00Z', NULL, '2025-11-29T00:31:52.281052Z'),
(31, 'radical', 'treasure', 'メ', 'This radical is <radical>treasure</radical> because "X marks the spot," as they say. Doesn''t it look like the X on a pirate treasure map? You want to go find that treasure now, right?!', 'https://api.wanikani.com/v2/subjects/31', 'https://www.wanikani.com/radicals/treasure', 2, 2, '2012-02-28T21:06:46Z', NULL, '2026-04-04T20:17:45.612577Z'),
(32, 'radical', 'thousand', '千', 'You have a slide supported by a big cross, which makes it so strong it can hold a lot of people at once. How many? A <radical>THOUSAND</radical>! Imagine a thousand people going down this slide. You can hear a voice trying to count them as they go: "ONE! TWO! THREE HUNDRED! FIVE HUNDRED!" and so on. Finally the last person slides down and the voice calls out: "A THOUSAND!" You think it''s over, but just as that group finishes, in come another thousand…', 'https://api.wanikani.com/v2/subjects/32', 'https://www.wanikani.com/radicals/thousand', 2, 2, '2012-02-28T21:07:15Z', NULL, '2025-11-07T23:10:32.794596Z'),
(33, 'radical', 'evening', '夕', 'This is the top half of a moon peeking out as it begins to rise. When does that happen? In the <radical>evening</radical>! Don''t confuse this with the moon radical 月. 夕 is for the evening, when the moon''s still low enough to be partly covered (by a mountain, for example).', 'https://api.wanikani.com/v2/subjects/33', 'https://www.wanikani.com/radicals/evening', 2, 2, '2012-02-28T21:09:46Z', NULL, '2026-04-01T09:46:52.810583Z'),
(34, 'radical', 'child', '子', 'This is the radical for <radical>child</radical>. Aww, see how they''re wearing a cap and have their little arms stretched out? You can almost hear them saying "pick me up!" A very child-like child.', 'https://api.wanikani.com/v2/subjects/34', 'https://www.wanikani.com/radicals/child', 2, 2, '2012-02-28T21:11:20Z', NULL, '2025-10-10T17:05:09.185984Z'),
(35, 'radical', 'small', '小', 'You see two fins around a barb, but when you look closer, you realize those fins are actually two tiny fish. Think how small these fins (and fish) would have to be to look so much smaller than an already small barb. Talk about small fry… Yeah, that''s why this is the radical for <radical>small</radical>.', 'https://api.wanikani.com/v2/subjects/35', 'https://www.wanikani.com/radicals/small', 2, 2, '2012-02-28T21:12:20Z', NULL, '2026-01-21T06:58:49.255116Z'),
(36, 'radical', 'bow', '弓', 'This radical looks like a fancy composite <radical>bow</radical> people would use to shoot at targets and definitely not any normal living animals. See how the middle part is being pulled back? Imagine holding this bow and firing it at a target shaped like a giant alligator-crab monster.', 'https://api.wanikani.com/v2/subjects/36', 'https://www.wanikani.com/radicals/bow', 2, 2, '2012-02-28T21:12:35Z', NULL, '2026-03-19T06:03:32.726396Z'),
(37, 'radical', 'flag', '尸', 'See the <radical>flag</radical> in this radical? There''s a pole with a flag on the end of it, blowing in the wind. Basically, this radical looks just like a flag.', 'https://api.wanikani.com/v2/subjects/37', 'https://www.wanikani.com/radicals/flag', 2, 2, '2012-02-28T21:12:56Z', NULL, '2026-01-16T13:39:34.753123Z'),
(38, 'radical', 'hair', '彡', 'These three streaks look like the flowing locks of someone''s <radical>hair</radical>. Pretty easy to see and remember that this is the hair radical, right?', 'https://api.wanikani.com/v2/subjects/38', 'https://www.wanikani.com/radicals/hair', 2, 2, '2012-02-28T21:13:17Z', NULL, '2025-11-14T21:46:55.985219Z'),
(39, 'radical', 'five', '五', 'If you use your imagination, this radical actually looks like the number "5." You just have to remove the vertical line in the bottom left, plus a few extra ends that stick out here and there. Once you do that, you have an easy way to remember that this radical means <radical>five</radical>.', 'https://api.wanikani.com/v2/subjects/39', 'https://www.wanikani.com/radicals/five', 2, 2, '2012-02-28T21:13:36Z', NULL, '2025-10-01T06:09:46.636647Z'),
(40, 'radical', 'heaven', '天', 'Remember the guy from the big radical? This is him again, but this time he''s so big his head is touching <radical>heaven</radical>. He''s looking up and has his arms stretched open toward heaven, and his big hair is poking into those heavenly clouds.', 'https://api.wanikani.com/v2/subjects/40', 'https://www.wanikani.com/radicals/heaven', 2, 2, '2012-02-28T21:14:06Z', NULL, '2026-02-18T07:22:58.736332Z'),
(41, 'radical', 'hand', '手', 'This is the <radical>hand</radical> radical. If you look at the palm of your right hand, the lines in it probably kinda look like the lines in 手. Sure it''s not a perfect match, and everyone''s got different hands, but basically this radical looks like the lines in your hand. 
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(1918, 'kanji', '井', '井', 'The <radical>well</radical> radical and the <kanji>well</kanji> kanji are the same.', 'https://api.wanikani.com/v2/subjects/1918', 'https://www.wanikani.com/kanji/%E4%BA%95', 14, 1, '2013-07-03T17:47:02.112188Z', NULL, '2026-01-29T00:45:32.176312Z'),
(834, 'kanji', '陽', '陽', 'This <radical>building</radical> has <radical>easy</radical> access to <kanji>sunshine</kanji>. The <kanji>sunlight</kanji> shines right in, because it''s a clear building.', 'https://api.wanikani.com/v2/subjects/834', 'https://www.wanikani.com/kanji/%E9%99%BD', 15, 1, '2012-05-01T19:51:32Z', NULL, '2026-03-24T15:11:49.36496Z'),
(867, 'kanji', '福', '福', 'When a <radical>spirit</radical> decides to live in your <radical>scarecrow</radical>, you''ll be granted good <kanji>luck</kanji> and good <kanji>fortune</kanji>. Crows won''t hang out in your farm. Everything you grow will become large and delicious. But not everyone is so lucky that a spirit will decide to live in their scarecrow. So maybe the luck was in you all along!', 'https://api.wanikani.com/v2/subjects/867', 'https://www.wanikani.com/kanji/%E7%A6%8F', 15, 1, '2012-08-28T07:55:40.572368Z', NULL, '2026-03-24T15:11:49.254524Z'),
(919, 'kanji', '技', '技', 'You can make your <radical>fingers</radical> <radical>branch</radical> out. It''s your special <kanji>skill</kanji>, a very advanced <kanji>technique</kanji>. Your fingers branch out into smaller fingers and you can hold things really well. You can type super-duper fast. And you can win any tickle fight. These are skills you have thanks to your branching fingers.', 'https://api.wanikani.com/v2/subjects/919', 'https://www.wanikani.com/kanji/%E6%8A%80', 15, 1, '2012-09-18T23:54:52.772281Z', NULL, '2026-03-24T15:11:49.290768Z'),
(922, 'kanji', '術', '術', 'There <radical>go</radical> some <radical>angel</radical>s with <radical>drop</radical>s on their shoulders. Carrying drops like that requires <kanji>technique</kanji>. It’s a real <kanji>art</kanji>.', 'https://api.wanikani.com/v2/subjects/922', 'https://www.wanikani.com/kanji/%E8%A1%93', 15, 1, '2012-09-18T23:56:16.894208Z', NULL, '2026-03-24T15:11:49.326388Z'),
(928, 'kanji', '寺', '寺', 'The <radical>temple</radical> radical and the <kanji>temple</kanji> kanji are exactly the same! Brilliant.', 'https://api.wanikani.com/v2/subjects/928', 'https://www.wanikani.com/kanji/%E5%AF%BA', 15, 1, '2012-09-19T22:20:32.266505Z', NULL, '2026-03-24T15:11:49.058816Z'),
(929, 'kanji', '岩', '岩', 'A <radical>mountain</radical> <radical>stone</radical> is probably going to be a really big stone. We''re talking about a <kanji>boulder</kanji> here.', 'https://api.wanikani.com/v2/subjects/929', 'https://www.wanikani.com/kanji/%E5%B2%A9', 15, 1, '2012-09-19T22:41:41.398718Z', NULL, '2026-03-24T15:11:49.068778Z'),
(930, 'kanji', '帰', '帰', 'You pick up your <radical>knife</radical> and <radical>broom</radical> because you''re getting ready to <kanji>return home</kanji>. There''ll be a lot of work to do when you return home — cooking, cleaning, fixing stuff — so your knife and broom are sure to come in handy.', 'https://api.wanikani.com/v2/subjects/930', 'https://www.wanikani.com/kanji/%E5%B8%B0', 15, 1, '2012-09-19T22:42:20.373365Z', NULL, '2026-03-24T15:11:49.07844Z'),
(931, 'kanji', '春', '春', 'When you see the <radical>spring</radical> <radical>sun</radical> you know it''s finally the  <kanji>spring</kanji> season.', 'https://api.wanikani.com/v2/subjects/931', 'https://www.wanikani.com/kanji/%E6%98%A5', 15, 1, '2012-09-19T22:42:46.477745Z', NULL, '2026-03-29T19:35:30.42184Z'),
(932, 'kanji', '昼', '昼', 'A giant <radical>shrimp</radical> appears on top of the <radical>sun</radical> after it rises high above the <radical>ground</radical>, and this is how you know it''s <kanji>noon</kanji>. The shrimp appears on the sun exactly at noon every day, to announce that it''s noon.', 'https://api.wanikani.com/v2/subjects/932', 'https://www.wanikani.com/kanji/%E6%98%BC', 15, 1, '2012-09-19T22:43:13.063739Z', NULL, '2026-03-31T03:54:27.535164Z'),
(933, 'kanji', '晴', '晴', 'The <radical>sun</radical> is out, the sky is <radical>blue</radical>, things have begun to <kanji>clear up</kanji>!', 'https://api.wanikani.com/v2/subjects/933', 'https://www.wanikani.com/kanji/%E6%99%B4', 15, 1, '2012-09-19T22:43:41.687268Z', NULL, '2026-03-29T19:00:51.773218Z'),
(934, 'kanji', '秋', '秋', '<radical>Grain</radical>s look like they''re on <radical>fire</radical> in <kanji>autumn</kanji>. They all turn red and orange and brown, the colors of fire. It''s also fun to set grains on fire in Autumn, since it''s getting colder.', 'https://api.wanikani.com/v2/subjects/934', 'https://www.wanikani.com/kanji/%E7%A7%8B', 15, 1, '2012-09-19T22:44:13.102245Z', NULL, '2026-03-24T15:11:49.115578Z'),
(935, 'kanji', '計', '計', 'If you want to <radical>say</radical> how big a <radical>cross</radical> is, you have to <kanji>measure</kanji> it. You can''t say the size of something without measuring it first.', 'https://api.wanikani.com/v2/subjects/935', 'https://www.wanikani.com/kanji/%E8%A8%88', 15, 1, '2012-09-19T22:44:45.683133Z', NULL, '2026-03-24T15:11:49.129981Z'),
(936, 'kanji', '列', '列', 'Take your <radical>yakuza</radical> <radical>knife</radical> and put it in a <kanji>row</kanji> with the others.', 'https://api.wanikani.com/v2/subjects/936', 'https://www.wanikani.com/kanji/%E5%88%97', 15, 1, '2012-09-19T22:45:22.889389Z', NULL, '2026-04-08T07:17:38.432586Z'),
(937, 'kanji', '区', '区', 'This <radical>cage</radical> with <radical>treasure</radical> in it is actually a map of the <kanji>district</kanji> the treasure is in.', 'https://api.wanikani.com/v2/subjects/937', 'https://www.wanikani.com/kanji/%E5%8C%BA', 15, 1, '2012-09-19T22:45:46.844454Z', NULL, '2026-03-24T15:11:49.160615Z'),
(938, 'kanji', '坂', '坂', '<radical>Dirt</radical> is being <radical>anti</radical>-social when it''s in the shape of a <kanji>slope</kanji>. Think about it — is there anything more annoying than having to walk up a steep slope? Why is the dirt here forming a slope?! Because the dirt is being anti-social, and a slope is how it tells you to stay away.', 'https://api.wanikani.com/v2/subjects/938', 'https://www.wanikani.com/kanji/%E5%9D%82', 15, 1, '2012-09-19T22:46:14.988622Z', NULL, '2026-03-24T15:11:49.169023Z'),
(939, 'kanji', '式', '式', 'A good <radical>ceremony</radical> is under <radical>construction</radical> for a long time. You can''t just make up a new ceremony on the spot. A ceremony is done a certain way because that''s the way it''s always been done. In short, to build a ceremony, you have to create a <kanji>ritual</kanji> first. Then, the ritual can be constructed into a bigger, more lavish <kanji>ceremony</kanji>.
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(1958, 'kanji', '零', '零', 'You get <radical>rain</radical> <radical>orders</radical>. Your orders are to make sure there is <kanji>zero</kanji> <kanji>spill</kanji>.', 'https://api.wanikani.com/v2/subjects/1958', 'https://www.wanikani.com/kanji/%E9%9B%B6', 46, 1, '2013-08-02T21:40:14.845224Z', NULL, '2025-11-25T02:27:09.777362Z'),
(1959, 'kanji', '碁', '碁', 'A <radical>crab</radical> moves a <radical>stone</radical> because he is playing the game <kanji>go</kanji>. You know this game, right? You put black or white stones on a board until you win the game. This is the Japanese game known as go. This crab is pretty good.', 'https://api.wanikani.com/v2/subjects/1959', 'https://www.wanikani.com/kanji/%E7%A2%81', 46, 1, '2013-08-02T21:40:44.482559Z', NULL, '2026-03-31T18:11:34.848247Z'),
(1960, 'kanji', '租', '租', 'Someone with a <radical>top hat</radical> comes and tells you that your <radical>grain</radical>s are going to be taxed from now on. Top hat man says there is a <kanji>tariff</kanji> that''s been enacted on grains. Rice? Triple the price. Wheat? Quadruple.', 'https://api.wanikani.com/v2/subjects/1960', 'https://www.wanikani.com/kanji/%E7%A7%9F', 46, 1, '2013-08-02T21:41:03.33682Z', NULL, '2025-10-01T06:10:00.756487Z'),
(1961, 'kanji', '幽', '幽', '<radical>Poop</radical> <radical>Poop</radical> <radical>Mountain</radical> is covered in poop because it is such a <kanji>secluded</kanji> place.', 'https://api.wanikani.com/v2/subjects/1961', 'https://www.wanikani.com/kanji/%E5%B9%BD', 46, 1, '2013-08-02T21:41:28.637971Z', NULL, '2025-10-01T06:10:00.761882Z'),
(1962, 'kanji', '泡', '泡', 'If a <radical>tsunami</radical> <radical>wrap</radical>s around itself, the resulting wave will create a lot of <kanji>bubbles</kanji>. You know how tsunamis wrap around once gravity kicks in, right? Well when that wave crashes, a whole lot of bubbles are created.', 'https://api.wanikani.com/v2/subjects/1962', 'https://www.wanikani.com/kanji/%E6%B3%A1', 46, 1, '2013-08-02T21:41:48.912217Z', NULL, '2026-01-30T23:49:29.051166Z'),
(1963, 'kanji', '癖', '癖', 'When you get <radical>sick</radical> you always eat a <radical>hot pepper</radical>. It''s a <kanji>habit</kanji> you''ve picked up and you can''t seem to shake it. One sniffle, one cough, and before you know it, you''re eating a hot pepper or two.', 'https://api.wanikani.com/v2/subjects/1963', 'https://www.wanikani.com/kanji/%E7%99%96', 46, 1, '2013-08-02T21:42:18.535432Z', NULL, '2025-10-01T06:10:00.784339Z'),
(1964, 'kanji', '鍛', '鍛', 'You want to turn your <radical>gold</radical> <radical>comb</radical> into a <radical>weapon</radical>, so you throw it into the <kanji>forge</kanji>.', 'https://api.wanikani.com/v2/subjects/1964', 'https://www.wanikani.com/kanji/%E9%8D%9B', 46, 1, '2013-08-02T21:42:46.188979Z', NULL, '2025-10-09T23:27:43.530279Z'),
(1965, 'kanji', '錬', '錬', 'The <radical>gold</radical> from the <radical>east</radical> needs <kanji>tempering</kanji> before it can be sold. The gold from the east is good, it just needs some tempering before it''s entirely presentable. You know, tempering like you''d do in a forge.', 'https://api.wanikani.com/v2/subjects/1965', 'https://www.wanikani.com/kanji/%E9%8C%AC', 46, 1, '2013-08-02T21:43:07.030373Z', NULL, '2025-10-09T23:27:43.530279Z'),
(1966, 'kanji', '穂', '穂', 'The part of the <radical>grain</radical> people <radical>favor</radical> the most is the <kanji>head of the plant</kanji>. You don''t eat the stems and leaves of rice or wheat plants, right? You eat the head where the grains are.', 'https://api.wanikani.com/v2/subjects/1966', 'https://www.wanikani.com/kanji/%E7%A9%82', 46, 1, '2013-08-02T21:43:35.078863Z', NULL, '2025-10-10T16:39:52.884641Z'),
(1967, 'kanji', '帝', '帝', 'You <radical>stand</radical> on a <radical>towel</radical> because you''re the <kanji>sovereign</kanji>. As a sovereign, you''re too important to be getting your shoes dirty. Everywhere you go, you''re standing on a towel — that''s how people know you''re the sovereign.', 'https://api.wanikani.com/v2/subjects/1967', 'https://www.wanikani.com/kanji/%E5%B8%9D', 46, 1, '2013-08-02T21:43:57.401204Z', NULL, '2026-01-11T23:40:37.8057Z'),
(1968, 'kanji', '瞬', '瞬', 'Your <radical>eye</radical> gets kicked with a <radical>cleat</radical> that came careening toward your <radical>forehead</radical> when it popped off someone doing a <radical>dance</radical>, and you <kanji>blink</kanji>.', 'https://api.wanikani.com/v2/subjects/1968', 'https://www.wanikani.com/kanji/%E7%9E%AC', 46, 1, '2013-08-02T21:44:22.815603Z', NULL, '2026-04-06T19:38:48.256629Z'),
(1969, 'kanji', '菊', '菊', 'If you pick the wrong kind of <radical>flowers</radical>, you''ll be put into <radical>prison</radical> with nothing but <radical>rice</radical> to eat. You''ll especially want to avoid picking <kanji>chrysanthemums</kanji>. ', 'https://api.wanikani.com/v2/subjects/1969', 'https://www.wanikani.com/kanji/%E8%8F%8A', 46, 1, '2013-08-02T21:44:44.015567Z', NULL, '2025-12-08T10:14:08.417037Z'),
(1970, 'kanji', '誇', '誇', '<radical>Say</radical> "<radical>two</radical> <radical>big</radical> <radical>prison</radical>s" with <kanji>pride</kanji>! Nobody said you can''t have pride after serving time in two big prisons. So say it with your chest!', 'https://api.wanikani.com/v2/subjects/1970', 'https://www.wanikani.com/kanji/%E8%AA%87', 46, 1, '2013-08-02T21:45:05.745519Z', NULL, '2025-12-08T10:14:08.417037Z'),
(1971, 'kanji', '庄', '庄', 'You set up a <radical>canopy</radical> over a patch of <radical>dirt</radical> because you''re setting up a <kanji>manor</kanji> here — you know, a big rural <kanji>estate</kanji>, probably with serfs and stuff.', 'https://api.wanikani.com/v2/subjects/1971', 'https://www.wanikani.com/kanji/%E5%BA%84', 46, 1, '2013-08-02T21:45:43.77676Z', NULL, '2026-04-06T18:24:53.012902Z'),
(1972, 'kanji', '阻', '阻', 'If you see a <radical>building</radical> wearing a giant <radical>top hat</radical>, beware! This building is a fake and it''s trying to <kanji>thwart</kanji> all of the plans the people in other buildings have.', 'https://api.wanikani.com/v2/subjects/1972', 'https://www.wanikani.com/kanji/%E9%98%BB', 46, 1, '2013-08-02T21:46:08.419318Z', NULL, '2025-10-10T16:47:32.419857Z'),
(1973, 'kanji', '黙', '黙', 'Your village wants to take the <radical>village</radical> <radical>dog</radical> and <radical>boil</radical> it, and you can think of no other response than <kanji>SHUT UP</kanji>! ', 'https://api.wanikani.com/v2/subjects/1973', 'https://www.wanikani.com/kanji/%E9%BB%99', 46, 1, '2013-08-02T21:46:31.081878Z', NULL, '2026-04-09T08:55:56.229376Z'),
(1974, 'kanji', '俵', '俵', 'The <radical>leader</radical> of your sad <radical>life</radical> aims a <radical>kick</radical> at the <kanji>straw sack</kanji> you are holding. This leader is in charge of making your life sad. The next step in the leader making your life suck is attempting to kick your straw sack out of your hands. Your sack holds all your valuables, so it''s not something you want to have kicked.', 'https://api.wanikani.com/v2/subjects/1974', 'https://www.wanikani.com/kanji/%E4%BF%B5', 46, 1, '2013-08-02T21:47:01.939021Z', NULL, '2025-10-08T23:31:05.530857Z'),
(1975, 'kanji', '綿', '綿', 'The <radical>white</radical> <radical>thread</radical> in your <radical>towel</radical> comes from <kanji>cotton</kanji>. We use cotton to make lots of things, like clothes and bedsheets. But white towels are always made from soft, fluffy cotton.', 'https://api.wanikani.com/v2/subjects/1975', 'https://www.wanikani.com/kanji/%E7%B6%BF', 46, 1, '2013-08-02T21:47:40.356796Z', NULL, '2025-10-01T06:10:00.871619Z'),
(1976, 'kanji', '架', '架', 'With the <radical>power</radical> of your <radical>mouth</radical> you command a <radical>tree</radical> to become a <kanji>shelf</kanji>. Most of the time one would have to use their hands and tools to turn a tree into a shelf, but you are capable of turning a tree into a shelf by using the power of your mouth.', 'https://api.wanikani.com/v2/subjects/1976', 'https://www.wanikani.com/kanji/%E6%9E%B6', 46, 1, '2013-08-02T21:48:04.052769Z', NULL, '2025-10-01T06:10:00.873627Z'),
(2119, 'kanji', '孔', '孔', 'You see a <radical>child</radical> with an <radical>umbrella</radical> in front of you. Suddenly, they fall straight down into a <kanji>cavity</kanji> in the road. It''s a big <kanji>hole</kanji>!', 'https://api.wanikani.com/v2/subjects/2119', 'https://www.wanikani.com/kanji/%E5%AD%94', 46, 1, '2014-05-01T18:47:56.744503Z', NULL, '2025-10-01T06:10:01.819549Z'),
(1977, 'kanji', '砕', '砕', 'Take this <radical>stone</radical> and throw it at <radical>nine</radical> <radical>cross</radical>es to <kanji>smash</kanji> them! It''s like old-fashioned bowling, but instead of rolling this stone to knock down the crosses, you want to completely smash them to bits!', 'https://api.wanikani.com/v2/subjects/1977', 'https://www.wanikani.com/kanji/%E7%A0%95', 47, 1, '2013-08-05T17:59:30.854129Z', NULL, '2025-10-09T23:21:30.153543Z'),
(1978, 'kanji', '粘', '粘', 'Your <radical>rice</radical> <radical>fortune</radical> is <kanji>sticky</kanji>. Rice is sticky. So is your rice fortune. Your fortune of rice is sticky because it is made up entirely of sticky rice.', 'https://api.wanikani.com/v2/subjects/1978', 'https://www.wanikani.com/kanji/%E7%B2%98', 47, 1, '2013-08-05T17:59:59.183982Z', NULL, '2026-02-16T22:38:00.752913Z'),
(1980, 'kanji', '欺', '欺', 'A <radical>crab</radical> will try to hide what it <radical>lack</radical>s with <kanji>deceit</kanji>. Lying, stealing, faking things—no type of deceit is too much for a crab.', 'https://api.wanikani.com/v2/subjects/1980', 'https://www.wanikani.com/kanji/%E6%AC%BA', 47, 1, '2013-08-05T18:09:55.740425Z', NULL, '2025-11-26T19:05:09.238484Z'),
(1981, 'kanji', '詐', '詐', 'They <radical>say</radical> the <radical>key</radical> to telling a <kanji>lie</kanji> is to totally believe the lie yourself. They say that if you believe your own lie, others will believe it as well. This is key.', 'https://api.wanikani.com/v2/subjects/1981', 'https://www.wanikani.com/kanji/%E8%A9%90', 47, 1, '2013-08-05T18:10:40.129808Z', NULL, '2025-10-01T06:10:00.898519Z'),
(1982, 'kanji', '霧', '霧', 'It''s <radical>rain</radical>ing on your <radical>spear</radical> that has <radical>winter</radical> <radical>power</radical>. When the warm rain hits your cold, winter spear, it creates <kanji>fog</kanji>.', 'https://api.wanikani.com/v2/subjects/1982', 'https://www.wanikani.com/kanji/%E9%9C%A7', 47, 1, '2013-08-05T18:11:03.185396Z', NULL, '2025-10-01T06:10:00.917291Z'),
(1983, 'kanji', '柳', '柳', 'A <radical>tree</radical> that is <radical>stamp</radical>ed with one pattern, then <radical>stamp</radical>ed with another pattern, over and over, is the <kanji>willow</kanji> tree. ', 'https://api.wanikani.com/v2/subjects/1983', 'https://www.wanikani.com/kanji/%E6%9F%B3', 47, 1, '2013-08-05T18:13:48.040025Z', NULL, '2025-10-01T06:10:00.933207Z'),
(1984, 'kanji', '伊', '伊', 'A <radical>leader</radical> and <radical>Wolverine</radical> take a <radical>slide</radical> to <kanji>Italy</kanji>. Wolverine’s leader is Professor X, and they are both sliding down a big slide to Italy. How fun!', 'https://api.wanikani.com/v2/subjects/1984', 'https://www.wanikani.com/kanji/%E4%BC%8A', 47, 1, '2013-08-05T18:14:16.724749Z', NULL, '2025-10-01T06:10:00.939946Z'),
(1985, 'kanji', '佐', '佐', 'The <radical>leader</radical> of a <radical>narwhal</radical> <radical>construction</radical> crew needs all the <kanji>help</kanji> he can get. The narwhals are beginning construction on an underwater city. The leader knows the narwhals are hard construction workers, but they’ll need some help building this city.', 'https://api.wanikani.com/v2/subjects/1985', 'https://www.wanikani.com/kanji/%E4%BD%90', 47, 1, '2013-08-05T18:14:41.802786Z', NULL, '2026-02-23T01:08:24.215405Z'),
(1986, 'kanji', '尺', '尺', 'This <radical>shrimp</radical> is the exact length of a <kanji>shaku</kanji>, or <kanji>Japanese foot</kanji>. That’s how they came up with this form of measurement. They measured the length of this shrimp and it was the length of a Japanese foot which they deemed the shaku. It’s equal to 30.3cm, very close to one imperial foot.', 'https://api.wanikani.com/v2/subjects/1986', 'https://www.wanikani.com/kanji/%E5%B0%BA', 47, 1, '2013-08-05T18:15:00.67367Z', NULL, '2026-01-29T00:39:53.26852Z'),
(1987, 'kanji', '哀', '哀', 'With a <radical>lid</radical>, you hit yourself in the <radical>mouth</radical> and then <radical>kick</radical> it like a <kanji>pathetic</kanji> loser. You kick the lid, even though it is your fault that you hit yourself in the mouth with it. It’s not the lid’s fault. You don’t need to kick it. You’re being pathetic.', 'https://api.wanikani.com/v2/subjects/1987', 'https://www.wanikani.com/kanji/%E5%93%80', 47, 1, '2013-08-05T18:17:29.131506Z', NULL, '2025-12-10T21:12:31.378587Z'),
(1988, 'kanji', '唇', '唇', 'A <radical>landslide</radical> came out of your <radical>mouth</radical> and created your <kanji>lips</kanji>. Before the landslide, you just had a wide open mouth hole.', 'https://api.wanikani.com/v2/subjects/1988', 'https://www.wanikani.com/kanji/%E5%94%87', 47, 1, '2013-08-05T18:17:47.633475Z', NULL, '2025-11-25T01:50:20.429937Z'),
(1989, 'kanji', '塀', '塀', 'In the <radical>dirt</radical> there are <radical>flag</radical>s and <radical>horns</radical> lined up with a <radical>lantern</radical> attached to them, making a <kanji>fence</kanji>. It''s a little weird looking, but these things are definitely supposed to fence something in.', 'https://api.wanikani.com/v2/subjects/1989', 'https://www.wanikani.com/kanji/%E5%A1%80', 47, 1, '2013-08-05T18:18:23.370027Z', NULL, '2025-10-01T06:10:00.956952Z'),
(1990, 'kanji', '墜', '墜', 'A <radical>building</radical> falls into the <radical>dirt</radical> when a <radical>pig</radical> with <radical>horns</radical> <kanji>crash</kanji>es into it. The building literally crashes to the ground when the horned pig attacks it.', 'https://api.wanikani.com/v2/subjects/1990', 'https://www.wanikani.com/kanji/%E5%A2%9C', 47, 1, '2013-08-05T18:18:42.433604Z', NULL, '2025-10-01T06:10:00.965698Z'),
(1991, 'kanji', '如', '如', 'With a <radical>woman</radical>''s <radical>mouth</radical>, you have a <kanji>likeness</kanji> to me.', 'https://api.wanikani.com/v2/subjects/1991', 'https://www.wanikani.com/kanji/%E5%A6%82', 47, 1, '2013-08-05T18:19:04.428637Z', NULL, '2026-03-30T10:30:14.743137Z'),
(1992, 'kanji', '婆', '婆', 'A <radical>wave</radical> crashes into a <radical>woman</radical>, transforming her into an <kanji>old woman</kanji>! The wave washes away all of the woman''s makeup, revealing her to be an old woman. The makeup she had on made her appear to be a much younger woman, but once the wave washed away her makeup, she was revealed for the old woman she is.', 'https://api.wanikani.com/v2/subjects/1992', 'https://www.wanikani.com/kanji/%E5%A9%86', 47, 1, '2013-08-05T18:19:30.791358Z', NULL, '2026-03-30T10:30:14.743137Z'),
(1994, 'kanji', '帽', '帽', 'You take a <radical>towel</radical> and wrap it around your head to keep the <radical>sun</radical> out of your <radical>eye</radical>s. You''ve invented... the <kanji>hat</kanji>!', 'https://api.wanikani.com/v2/subjects/1994', 'https://www.wanikani.com/kanji/%E5%B8%BD', 47, 1, '2013-08-05T18:20:31.880817Z', NULL, '2026-01-08T01:12:56.284365Z'),
(1995, 'kanji', '幣', '幣', 'That <radical>penguin</radical> over there seems to have a <radical>towel</radical> stuffed with <kanji>cash</kanji>.', 'https://api.wanikani.com/v2/subjects/1995', 'https://www.wanikani.com/kanji/%E5%B9%A3', 47, 1, '2013-08-05T18:20:56.545961Z', NULL, '2025-10-01T06:10:01.003959Z'),
(1996, 'kanji', '恨', '恨', 'A <radical>soul</radical> will only inhabit a <radical>root</radical> if it''s holding a <kanji>grudge</kanji>. Have you ever seen a nice, haunted tree? No! They''re always angry and trying to get someone back for something.', 'https://api.wanikani.com/v2/subjects/1996', 'https://www.wanikani.com/kanji/%E6%81%A8', 47, 1, '2013-08-05T18:21:16.285565Z', NULL, '2026-01-29T00:33:25.633876Z'),
(1997, 'kanji', '憎', '憎', 'The <radical>soul</radical> <radical>mask</radical> helps you to see the deepest part of anyone''s soul. You look around and in all the people you only see <kanji>hate</kanji>.', 'https://api.wanikani.com/v2/subjects/1997', 'https://www.wanikani.com/kanji/%E6%86%8E', 47, 1, '2013-08-05T18:21:38.502111Z', NULL, '2026-01-29T00:33:25.633876Z'),
(1998, 'kanji', '憩', '憩', 'You keep your <radical>tongue</radical> to your <radical>self</radical> to give your <radical>heart</radical> a <kanji>rest</kanji>. You’ve been talking and moving your tongue around all day expressing your feelings. This has tired both your tongue and your heart out, so you stop your tongue moving and decide that you need some self rest time.', 'https://api.wanikani.com/v2/subjects/1998', 'https://www.wanikani.com/kanji/%E6%86%A9', 47, 1, '2013-08-05T18:21:58.809065Z', NULL, '2026-02-24T00:33:18.69922Z'),
(1999, 'kanji', '扇', '扇', 'After passing through a <radical>door</radical>, you use a <radical>feather</radical> to put the finishing touches on a <kanji>folding fan</kanji>. The door leads to your folding fan workshop where you make all your folding fans. This folding fan is now complete that you’ve added a feather to it. How lovely it is.', 'https://api.wanikani.com/v2/subjects/1999', 'https://www.wanikani.com/kanji/%E6%89%87', 47, 1, '2013-08-05T18:22:22.291634Z', NULL, '2025-10-01T06:10:01.020741Z'),
(2000, 'kanji', '扉', '扉', 'What would a <radical>door</radical> <radical>criminal</radical> steal? A <kanji>door</kanji>, of course, but specifically a <kanji>hinged door</kanji>. You know, the kind that swings open and shut? That''s the kind of door 扉 means.', 'https://api.wanikani.com/v2/subjects/2000', 'https://www.wanikani.com/kanji/%E6%89%89', 47, 1, '2013-08-05T18:22:42.741315Z', NULL, '2026-01-14T18:14:32.006773Z'),
(2001, 'kanji', '挿', '挿', 'You have <radical>fingers</radical> in the <radical>thousand</radical>s and while looking up at the <radical>sun</radical> you decide you want to <kanji>insert</kanji> them in there.', 'https://api.wanikani.com/v2/subjects/2001', 'https://www.wanikani.com/kanji/%E6%8C%BF', 47, 1, '2013-08-05T18:23:04.118066Z', NULL, '2025-10-01T06:10:01.030869Z'),
(2002, 'kanji', '掌', '掌', 'If you want to cover a <radical>Viking</radical>''s <radical>mouth</radical> with your <radical>hand</radical>, you have to use your <kanji>palm</kanji>. Why the palm? Well, if you do it knuckles-to-mouth, you''re sort of just punching the Viking… and you don''t want a punch a Viking. That''s why you use the palm.', 'https://api.wanikani.com/v2/subjects/2002', 'https://www.wanikani.com/kanji/%E6%8E%8C', 47, 1, '2013-08-05T18:23:30.034812Z', NULL, '2026-01-31T00:04:45.380369Z'),
(2003, 'kanji', '滴', '滴', 'A <radical>tsunami</radical> hits your <radical>mohawk</radical> and it begins to <kanji>drip</kanji>. The water from the tsunami continues to drip from your mohawk long after the tsunami has passed. There’s a lot of water in your hair now, so it’s probably going to drip for a while.', 'https://api.wanikani.com/v2/subjects/2003', 'https://www.wanikani.com/kanji/%E6%BB%B4', 47, 1, '2013-08-05T18:23:52.183151Z', NULL, '2025-10-01T06:10:01.055008Z'),
(2004, 'kanji', '炊', '炊', 'Without a <radical>fire</radical>, you will <radical>lack</radical> the ability to <kanji>cook</kanji> anything. You really need a fire to cook properly. Having a fire will make sure any cooking endeavors you attempt will not fail.', 'https://api.wanikani.com/v2/subjects/2004', 'https://www.wanikani.com/kanji/%E7%82%8A', 47, 1, '2013-08-05T18:24:33.267004Z', NULL, '2025-10-01T06:10:01.060944Z'),
(2005, 'kanji', '爽', '爽', 'A <radical>big</radical> <radical>treasure</radical> <radical>treasure</radical> <radical>treasure</radical> <radical>treasure</radical> is <kanji>refreshing</kanji>! Sorry, I can’t say treasure treasure treasure treasure without saying it four times. See? I did it again. Anyway, this big treasure treasure treasure treasure is really refreshing. It’s been a long time since you found a treasure treasure treasure treasure, so finding this big one is really refreshing.', 'https://api.wanikani.com/v2/subjects/2005', 'https://www.wanikani.com/kanji/%E7%88%BD', 47, 1, '2013-08-05T18:24:59.537365Z', NULL, '2026-02-04T19:17:42.927403Z'),
(2006, 'kanji', '畳', '畳', 'In the <radical>rice paddy</radical> there is a <radical>forehead</radical> with a <radical>top hat</radical>. It sits atop an area of <kanji>tatami mat</kanji>s.', 'https://api.wanikani.com/v2/subjects/2006', 'https://www.wanikani.com/kanji/%E7%95%B3', 47, 1, '2013-08-05T18:25:25.136476Z', NULL, '2025-10-09T21:25:09.821502Z'),
(2007, 'kanji', '瞭', '瞭', 'Rub <radical>charcoal</radical> under your <radical>eye</radical>s if you want to see <kanji>clear</kanji>ly. Sports players also rub charcoal under their eyes to see nice and clear in the bright sun.', 'https://api.wanikani.com/v2/subjects/2007', 'https://www.wanikani.com/kanji/%E7%9E%AD', 47, 1, '2013-08-05T18:26:45.721735Z', NULL, '2025-10-01T06:10:01.066876Z'),
(2009, 'kanji', '胴', '胴', 'The <radical>moon</radical> is the <radical>same</radical> as your <kanji>torso</kanji>. You must have a really huge torso for it to be the same as the moon.', 'https://api.wanikani.com/v2/subjects/2009', 'https://www.wanikani.com/kanji/%E8%83%B4', 47, 1, '2013-08-05T18:27:37.036756Z', NULL, '2025-10-01T06:10:01.080494Z'),
(2011, 'kanji', '虹', '虹', 'An <radical>insect</radical> specializing in <radical>construction</radical> builds a <kanji>rainbow</kanji>. Did you ever wonder where rainbows come from? Construction insects build them. Construction insects build rainbows.', 'https://api.wanikani.com/v2/subjects/2011', 'https://www.wanikani.com/kanji/%E8%99%B9', 47, 1, '2013-08-05T18:28:21.386925Z', NULL, '2025-10-01T06:10:01.089381Z'),
(2012, 'kanji', '帳', '帳', 'Take your <radical>towel</radical> and make it <radical>long</radical>. It has to be longer than that! For this will be your <kanji>notebook</kanji>, which you will write all your notes in.', 'https://api.wanikani.com/v2/subjects/2012', 'https://www.wanikani.com/kanji/%E5%B8%B3', 48, 1, '2013-08-16T22:25:09.027871Z', NULL, '2025-10-01T06:10:01.102335Z'),
(2013, 'kanji', '蚊', '蚊', 'The type of <radical>insect</radical> that ruins your <radical>writing</radical> is the <kanji>mosquito</kanji>. You''re trying to write, when you hear that horrible high-pitched mosquito noise in your ear. You jerk your head and swat and it''s gone. But when you look down, there''s lines all over what you were writing.', 'https://api.wanikani.com/v2/subjects/2013', 'https://www.wanikani.com/kanji/%E8%9A%8A', 48, 1, '2013-08-16T22:26:02.201214Z', NULL, '2025-10-01T06:10:01.112202Z'),
(2014, 'kanji', '蛇', '蛇', 'There is an <radical>insect</radical> on the <radical>roof</radical> in a <radical>spoon</radical>. It''s there for the eating, and it''s how you plan to attract a <kanji>snake</kanji> to your roof.', 'https://api.wanikani.com/v2/subjects/2014', 'https://www.wanikani.com/kanji/%E8%9B%87', 48, 1, '2013-08-16T22:26:28.883396Z', NULL, '2025-10-01T06:10:01.118824Z'),
(2016, 'kanji', '辱', '辱', 'The <radical>landslide</radical> <radical>measurement</radical> <kanji>humiliate</kanji>s you. You told everyone you couldn''t come to work, that your house had been destroyed and your car was carried away, but then scientists measured the landslide, and it only went a few feet.', 'https://api.wanikani.com/v2/subjects/2016', 'https://www.wanikani.com/kanji/%E8%BE%B1', 48, 1, '2013-08-16T22:27:16.890898Z', NULL, '2025-11-25T01:50:20.429937Z'),
(2017, 'kanji', '鉢', '鉢', 'Melt down this <radical>gold</radical> <radical>book</radical> and recast it as a <kanji>flower pot</kanji>. A solid gold book is too heavy to hold and too shiny to read, but a solid gold flower pot would make a fancy new addition to your garden.', 'https://api.wanikani.com/v2/subjects/2017', 'https://www.wanikani.com/kanji/%E9%89%A2', 48, 1, '2013-08-16T22:27:42.361243Z', NULL, '2025-10-01T06:10:01.125595Z'),
(2020, 'kanji', '霜', '霜', '<radical>Rain</radical> falls off a <radical>tree</radical> and lands in your <radical>eye</radical> where it turns to <kanji>frost</kanji>. It turns to frost because it’s super cold outside and your body is freezing. The rain that fell off the tree turns to frost as soon as it hits your eye.', 'https://api.wanikani.com/v2/subjects/2020', 'https://www.wanikani.com/kanji/%E9%9C%9C', 48, 1, '2013-08-16T22:29:06.09059Z', NULL, '2025-10-01T06:10:01.157153Z'),
(2021, 'kanji', '飢', '飢', 'You’re so hungry that you <radical>eat</radical> a <radical>table</radical> so you won’t <kanji>starve</kanji>. If you don’t eat this table, you will most definitely starve, so you eat the table to stay alive.', 'https://api.wanikani.com/v2/subjects/2021', 'https://www.wanikani.com/kanji/%E9%A3%A2', 48, 1, '2013-08-16T22:29:38.731738Z', NULL, '2025-10-01T06:10:01.167751Z'),
(2022, 'kanji', '餓', '餓', 'If you have nothing to <radical>eat</radical> but your <radical>ego</radical>, you''ll <kanji>starve</kanji>. You can''t eat it, and your ego is keeping you from accepting actual food or help from other people.', 'https://api.wanikani.com/v2/subjects/2022', 'https://www.wanikani.com/kanji/%E9%A4%93', 48, 1, '2013-08-16T22:30:00.54762Z', NULL, '2025-10-01T06:10:01.174336Z'),
(2023, 'kanji', '畜', '畜', 'In the <radical>mysterious</radical> <radical>rice paddy</radical> there is some <kanji>livestock</kanji>. This livestock is also mysterious because no one knows where it came from. The mysterious livestock are only seen in the mysterious rice paddy. How mysterious indeed.', 'https://api.wanikani.com/v2/subjects/2023', 'https://www.wanikani.com/kanji/%E7%95%9C', 48, 1, '2013-08-16T22:30:25.561512Z', NULL, '2025-10-09T19:56:27.081206Z'),
(2024, 'kanji', '迅', '迅', 'When you ride a <radical>scooter</radical>, you wear a <radical>cape</radical> and carry a <radical>cross</radical> in order to move at a <kanji>swift</kanji> speed. The cape gives you a swiftness buff, naturally, and the cross lets you pray to a divine power to help you move ever more swiftly down the road.', 'https://api.wanikani.com/v2/subjects/2024', 'https://www.wanikani.com/kanji/%E8%BF%85', 48, 1, '2013-08-16T22:30:47.966008Z', NULL, '2026-02-23T00:57:41.840937Z'),
(2025, 'kanji', '騎', '騎', 'This <radical>horse</radical> may look <radical>odd</radical> but it’s actually perfect for <kanji>horse riding</kanji>!', 'https://api.wanikani.com/v2/subjects/2025', 'https://www.wanikani.com/kanji/%E9%A8%8E', 48, 1, '2013-08-16T22:31:11.808437Z', NULL, '2025-11-14T00:31:25.889285Z'),
(2026, 'kanji', '蓄', '蓄', '<radical>Flowers</radical> are <radical>mysterious</radical>ly appearing in the <radical>rice paddy</radical>. No matter what you do to them, they continue to <kanji>amass</kanji>.', 'https://api.wanikani.com/v2/subjects/2026', 'https://www.wanikani.com/kanji/%E8%93%84', 48, 1, '2013-08-16T22:31:40.690675Z', NULL, '2025-10-09T21:28:35.370688Z'),
(2027, 'kanji', '尽', '尽', 'You see <radical>shrimp</radical> on <radical>ice</radical> at the market in the morning. "I''ll get some on the way home" you think to yourself. Later that evening, you see no shrimp, just ice. The supply of shrimp has been <kanji>exhaust</kanji>ed. It''s all gone! You never thought they''d <kanji>use up</kanji> their shrimp supply so quickly.', 'https://api.wanikani.com/v2/subjects/2027', 'https://www.wanikani.com/kanji/%E5%B0%BD', 48, 1, '2013-08-16T22:32:01.104394Z', NULL, '2026-01-29T00:39:53.26852Z'),
(2028, 'kanji', '彩', '彩', 'You use a <radical>cleat</radical> to climb a <radical>tree</radical> and your <radical>hair</radical> gets the same <kanji>coloring</kanji> as the foliage because your hair is like a chameleon. The coloring of your hair changes to whatever color is around you, so you use your cleats to climb trees to make your hair turn green and brown, and in the fall, yellow and orange and red!', 'https://api.wanikani.com/v2/subjects/2028', 'https://www.wanikani.com/kanji/%E5%BD%A9', 48, 1, '2013-08-16T22:32:23.781277Z', NULL, '2025-11-24T20:34:39.359876Z'),
(2029, 'kanji', '憶', '憶', 'When your <radical>soul</radical> has an <radical>idea</radical> it''s just a <kanji>recollection</kanji> of something you already know. Only your brain can have original ideas, so when your soul tries to come up with one, it''s just a recollection of something you thought before now.', 'https://api.wanikani.com/v2/subjects/2029', 'https://www.wanikani.com/kanji/%E6%86%B6', 48, 1, '2013-08-16T22:32:45.587534Z', NULL, '2026-02-24T00:46:03.850495Z'),
(2030, 'kanji', '溶', '溶', 'The <radical>tsunami</radical> hits your <radical>form</radical> and you begin to <kanji>melt</kanji>. You are a witch and water makes you melt. The tsunami is a lot of water, so once it touches your form, you begin to melt.', 'https://api.wanikani.com/v2/subjects/2030', 'https://www.wanikani.com/kanji/%E6%BA%B6', 48, 1, '2013-08-16T22:33:13.179212Z', NULL, '2025-10-09T19:53:13.017243Z'),
(2031, 'kanji', '耐', '耐', 'You take a <radical>rake</radical> in for a <radical>measurement</radical> but it is <kanji>resistant</kanji>. The rake doesn’t want to have its measurements taken. The rake is resistant to have any measurement taken because it feels inferior to the other rakes and doesn’t want to be embarrassed if it ends up being smaller than the others.', 'https://api.wanikani.com/v2/subjects/2031', 'https://www.wanikani.com/kanji/%E8%80%90', 48, 1, '2013-08-16T22:33:36.217743Z', NULL, '2025-10-01T06:10:01.23365Z'),
(2032, 'kanji', '踊', '踊', 'Your <radical>foot</radical>, as your <radical>mama</radical> says, was given the <radical>task</radical> to <kanji>dance</kanji>. Shake those two foots your mama gave you and dance dance dance!', 'https://api.wanikani.com/v2/subjects/2032', 'https://www.wanikani.com/kanji/%E8%B8%8A', 48, 1, '2013-08-16T22:34:00.320435Z', NULL, '2025-10-01T06:10:01.241262Z'),
(2033, 'kanji', '賢', '賢', 'Your <radical>servant</radical> uses a <radical>stool</radical> to break open <radical>shellfish</radical>. This is really <kanji>clever</kanji>, because shucking shellfish is a lot of work. It''s also a <kanji>wise</kanji> move, because it''ll save him time that he can spend on all his other servant chores.', 'https://api.wanikani.com/v2/subjects/2033', 'https://www.wanikani.com/kanji/%E8%B3%A2', 48, 1, '2013-08-16T22:34:24.331003Z', NULL, '2026-02-04T19:14:35.18523Z'),
(2034, 'kanji', '輝', '輝', 'The <radical>light</radical> shines on your <radical>forehead</radical> in your <radical>car</radical> with a great <kanji>radiance</kanji>. The car you are in is a convertible, so the light shines right onto your big bald forehead. The light has a pretty powerful radiance as it is, but the sheen from this light hitting your forehead is the most powerful radiance ever witnessed by man.', 'https://api.wanikani.com/v2/subjects/2034', 'https://www.wanikani.com/kanji/%E8%BC%9D', 48, 1, '2013-08-16T22:35:00.68697Z', NULL, '2025-10-01T06:10:01.251649Z'),
(2035, 'kanji', '脅', '脅', 'There''s <radical>power</radical>, <radical>power</radical>, and <radical>power</radical> stacked on top of the <radical>moon</radical>, <kanji>threaten</kanji>ing to bring it down!', 'https://api.wanikani.com/v2/subjects/2035', 'https://www.wanikani.com/kanji/%E8%84%85', 48, 1, '2013-08-16T22:35:38.414446Z', NULL, '2025-10-01T06:10:01.257691Z'),
(2036, 'kanji', '麻', '麻', 'This <radical>canopy</radical> of <radical>tree</radical>s isn''t actually a canopy of trees at all. When you look closely, you see these trees are actually giant stalks of <kanji>hemp</kanji>.', 'https://api.wanikani.com/v2/subjects/2036', 'https://www.wanikani.com/kanji/%E9%BA%BB', 48, 1, '2013-08-16T22:36:01.198412Z', NULL, '2025-10-01T06:10:01.25941Z'),
(2037, 'kanji', '灯', '灯', '<radical>Fire</radical> you use to light up the <radical>street</radical> needs to go in a <kanji>lamp</kanji>. Campfires, matches? No, none of those work. You need bright, safe lamps to keep the street nice at night.', 'https://api.wanikani.com/v2/subjects/2037', 'https://www.wanikani.com/kanji/%E7%81%AF', 48, 1, '2013-08-16T22:36:29.327207Z', NULL, '2026-04-07T20:20:40.00989Z'),
(2038, 'kanji', '咲', '咲', 'When a flower looks like a <radical>mouth</radical> with <radical>horns</radical> that reach up to <radical>heaven</radical>, you know it''s in <kanji>blossom</kanji>. It''s all opened up like a mouth, and the pistil and stamen are like horns reaching up to heaven for its sunlight and rain.', 'https://api.wanikani.com/v2/subjects/2038', 'https://www.wanikani.com/kanji/%E5%92%B2', 48, 1, '2013-08-16T22:36:50.5812Z', NULL, '2025-10-01T06:10:01.272714Z'),
(2039, 'kanji', '培', '培', 'Your <radical>dirt</radical> needs a  <radical>clown</radical> in it if you want to <kanji>cultivate</kanji> good crops. Clowns act as a natural fertilizer, and this will make it super easy to cultivate any crops you could ever want in this dirt. Isn''t nature amazing?', 'https://api.wanikani.com/v2/subjects/2039', 'https://www.wanikani.com/kanji/%E5%9F%B9', 48, 1, '2013-08-16T22:37:13.068174Z', NULL, '2025-10-01T06:10:01.275085Z'),
(2040, 'kanji', '悔', '悔', 'If you try to put your <radical>soul</radical> into <radical>every</radical>thing, you''ll <kanji>regret</kanji> it. It''s not so much that putting your soul into things is bad, but every single thing? You''ll burn out immediately. You won''t be able to be good at any of those things. And you''ll regret all the time you wasted trying to be the best at everything.', 'https://api.wanikani.com/v2/subjects/2040', 'https://www.wanikani.com/kanji/%E6%82%94', 48, 1, '2013-08-16T22:37:44.06417Z', NULL, '2026-01-29T00:33:25.633876Z'),
(2042, 'kanji', '遂', '遂', 'A <radical>scooter</radical> with <radical>horns</radical> with a <radical>pig</radical> riding on it will be able to <kanji>accomplish</kanji> anything.', 'https://api.wanikani.com/v2/subjects/2042', 'https://www.wanikani.com/kanji/%E9%81%82', 48, 1, '2013-08-16T22:39:10.048098Z', NULL, '2025-10-10T00:18:48.389539Z'),
(2043, 'kanji', '班', '班', 'If the <radical>king</radical> gives you a <radical>knife</radical> you become part of his <kanji>squad</kanji>. Every king has a knife squad or two protecting him and making sure his subjects keep in line.', 'https://api.wanikani.com/v2/subjects/2043', 'https://www.wanikani.com/kanji/%E7%8F%AD', 48, 1, '2013-08-16T22:39:39.297715Z', NULL, '2025-10-01T06:10:01.318711Z'),
(2044, 'kanji', '塗', '塗', 'A <radical>tsunami</radical> <radical>surplus</radical> will cover all the <radical>dirt</radical> with <kanji>paint</kanji>. The surplus of tsunamis will strike the paint factories first (everyone knows paint factories are built close to the ocean). Then the paint will flow over all the dirt and paint it a ton of rainbow colors.', 'https://api.wanikani.com/v2/subjects/2044', 'https://www.wanikani.com/kanji/%E5%A1%97', 48, 1, '2013-08-16T22:40:06.199892Z', NULL, '2025-10-01T06:10:01.314824Z'),
(2045, 'kanji', '斜', '斜', 'You have a <radical>surplus</radical> of <radical>ladle</radical>s laid out <kanji>diagonally</kanji> in front of you. Why are they diagonal? And why do you have so many ladles? Why the surplus? Hang on, we''ll get there.', 'https://api.wanikani.com/v2/subjects/2045', 'https://www.wanikani.com/kanji/%E6%96%9C', 48, 1, '2013-08-16T22:40:35.042874Z', NULL, '2025-12-15T03:20:33.272894Z'),
(2046, 'kanji', '殴', '殴', 'Your <radical>district</radical> is full of <radical>weapons</radical>, but everyone prefers to <kanji>punch</kanji> each other. When everyone''s armed, things can escalate quickly, so it''s better to stick to fists to be safe.', 'https://api.wanikani.com/v2/subjects/2046', 'https://www.wanikani.com/kanji/%E6%AE%B4', 48, 1, '2013-08-16T22:41:14.201726Z', NULL, '2026-02-04T19:14:53.500929Z'),
(2047, 'kanji', '盾', '盾', 'On a <radical>cliff</radical>, the <radical>pope</radical> is holding a <kanji>shield</kanji>. The pope is near the edge of the cliff and is using the shield to fend off demons. The demons want to shove the pope off the cliff, but the pope is using his holy shield of popery to fend them off.', 'https://api.wanikani.com/v2/subjects/2047', 'https://www.wanikani.com/kanji/%E7%9B%BE', 48, 1, '2013-08-16T22:41:46.388782Z', NULL, '2025-11-26T07:56:53.037423Z'),
(2048, 'kanji', '穫', '穫', 'You need to feed this <radical>grain</radical> to a <radical>flower</radical> wearing <radical>turkey</radical> on a <radical>stool</radical> so you start the <kanji>harvest</kanji>. Grains don''t pick themselves, you have to harvest them.', 'https://api.wanikani.com/v2/subjects/2048', 'https://www.wanikani.com/kanji/%E7%A9%AB', 48, 1, '2013-08-16T22:42:15.620546Z', NULL, '2025-11-25T01:38:54.284696Z'),
(2050, 'kanji', '駒', '駒', 'The <radical>horse</radical> who can write a <radical>paragraph</radical> gets to be a <kanji>chess piece</kanji>. Only the most erudite of horses gets selected to be a chess piece. The knight’s chess piece is represented by a horse, and for a horse to earn this honor, they must first write a paragraph explaining why they deserve the honor.', 'https://api.wanikani.com/v2/subjects/2050', 'https://www.wanikani.com/kanji/%E9%A7%92', 49, 1, '2013-08-19T16:51:12.396242Z', NULL, '2026-01-29T01:16:01.747685Z'),
(2052, 'kanji', '抽', '抽', 'Your <radical>fingers</radical> give you a good <radical>reason</radical> to <kanji>extract</kanji> things. You extract juice from fruits, oil from seeds, and coffee from beans. Why? Because you have fingers! That''s your reason.', 'https://api.wanikani.com/v2/subjects/2052', 'https://www.wanikani.com/kanji/%E6%8A%BD', 49, 1, '2013-08-19T16:52:09.318149Z', NULL, '2025-10-01T06:10:01.371206Z'),
(2053, 'kanji', '誓', '誓', 'With your <radical>fingers</radical> under an <radical>axe</radical>, you <radical>say</radical> a <kanji>vow</kanji>. A vow is a sacred promise, so you have to be really serious when you say one. That''s why you do it with an axe hovering above your fingers—it''s a reminder that if you break this vow your fingers are gonna get chopped off.', 'https://api.wanikani.com/v2/subjects/2053', 'https://www.wanikani.com/kanji/%E8%AA%93', 49, 1, '2013-08-19T16:59:01.703034Z', NULL, '2025-10-01T06:10:01.37525Z'),
(2054, 'kanji', '悟', '悟', 'Your <radical>soul</radical> connects to <radical>five</radical> different <radical>mouths</radical>, allowing you to <kanji>realize</kanji> something. You can realize profound truths about the world with these five mouths speaking to your soul.', 'https://api.wanikani.com/v2/subjects/2054', 'https://www.wanikani.com/kanji/%E6%82%9F', 49, 1, '2013-08-19T16:59:29.662341Z', NULL, '2026-01-29T00:33:25.633876Z'),
(2055, 'kanji', '拓', '拓', 'You use your <radical>fingers</radical> and a <radical>stone</radical> to begin <kanji>cultivation</kanji> of the land. You use your fingers to till the soil, the stone to flatten the ground, and you carefully poke the seeds into the dirt and then use the stone to smash them further down.', 'https://api.wanikani.com/v2/subjects/2055', 'https://www.wanikani.com/kanji/%E6%8B%93', 49, 1, '2013-08-19T16:59:55.925957Z', NULL, '2025-10-09T21:16:32.062767Z'),
(2056, 'kanji', '拘', '拘', 'You run your <radical>fingers</radical> along the words of a  <radical>paragraph</radical>. You are learning about the law because you plan to <kanji>arrest</kanji> somebody.', 'https://api.wanikani.com/v2/subjects/2056', 'https://www.wanikani.com/kanji/%E6%8B%98', 49, 1, '2013-08-19T17:00:19.742926Z', NULL, '2026-01-29T01:16:01.747685Z'),
(2057, 'kanji', '礎', '礎', 'There’s a <radical>stone</radical>, a <radical>tree</radical>, another <radical>tree</radical>, and a <radical>coat rack</radical>. That stone and two trees will make the perfect <kanji>foundation</kanji>, or <kanji>cornerstone</kanji>, for a house to put that coat rack in! This stone is flat and heavy and both of the trees are flexible and durable.', 'https://api.wanikani.com/v2/subjects/2057', 'https://www.wanikani.com/kanji/%E7%A4%8E', 49, 1, '2013-08-19T17:00:47.805816Z', NULL, '2025-10-01T06:10:01.399213Z'),
(2058, 'kanji', '鶴', '鶴', 'On the <radical>roof</radical> there''s some type of <radical>turkey</radical> <radical>bird</radical>, but thinner and longer. You look closer and realize it''s a <kanji>crane</kanji>.', 'https://api.wanikani.com/v2/subjects/2058', 'https://www.wanikani.com/kanji/%E9%B6%B4', 49, 1, '2013-08-19T17:01:21.369528Z', NULL, '2025-11-25T01:38:54.284696Z'),
(2059, 'kanji', '刈', '刈', 'Take your greatest <radical>treasure</radical>, hold a <radical>knife</radical> nice and close to it, and <kanji>prune</kanji> away all the weak and dead bits.', 'https://api.wanikani.com/v2/subjects/2059', 'https://www.wanikani.com/kanji/%E5%88%88', 49, 1, '2013-08-19T17:01:46.134326Z', NULL, '2025-10-01T06:10:01.406709Z'),
(2060, 'kanji', '剛', '剛', 'A <radical>hill</radical> <radical>knife</radical> is the most <kanji>sturdy</kanji> knife you can find.', 'https://api.wanikani.com/v2/subjects/2060', 'https://www.wanikani.com/kanji/%E5%89%9B', 49, 1, '2013-08-19T17:02:11.900875Z', NULL, '2025-10-01T06:10:01.42563Z'),
(2061, 'kanji', '唯', '唯', 'The <radical>mouth</radical> of that <radical>turkey</radical> is <kanji>solely</kanji> his. It’s very unique, so that mouth could belong to no other turkey but him. That mouth is solely his.', 'https://api.wanikani.com/v2/subjects/2061', 'https://www.wanikani.com/kanji/%E5%94%AF', 49, 1, '2013-08-19T17:02:36.624158Z', NULL, '2025-11-25T01:38:54.284696Z'),
(2062, 'kanji', '壇', '壇', 'On the <radical>dirt</radical> there is a <radical>lid</radical> trying to cover the number of <radical>times</radical> the <radical>dawn</radical> has risen here. You walk over and pull the lid off and the whole thing transforms into a <kanji>podium</kanji>. A podium for the dawn to tell you how many times it''s risen over this dirt over and over again. It just keeps going and you realize the lid was here because this dang podium can''t seem to keep a lid on it! (Get it? Figure of speech!)', 'https://api.wanikani.com/v2/subjects/2062', 'https://www.wanikani.com/kanji/%E5%A3%87', 49, 1, '2013-08-19T17:03:07.57119Z', NULL, '2025-10-01T06:10:01.443689Z'),
(2063, 'kanji', '尼', '尼', 'You give a <radical>flag</radical> and a <radical>spoon</radical> to a <kanji>nun</kanji> as an offering. You give her this flag and this spoon because they are very precious to you and you want to show the nun how serious you are about repenting for your evil deeds.', 'https://api.wanikani.com/v2/subjects/2063', 'https://www.wanikani.com/kanji/%E5%B0%BC', 49, 1, '2013-08-19T17:03:28.209596Z', NULL, '2025-10-01T06:10:01.445614Z'),
(2064, 'kanji', '概', '概', 'Bite a <radical>tree</radical>''s <radical>root</radical> with your <radical>fang</radical> to get an <kanji>approximation</kanji> on its age. It won''t be exact, this isn''t scientific or anything, but it will be pretty close.', 'https://api.wanikani.com/v2/subjects/2064', 'https://www.wanikani.com/kanji/%E6%A6%82', 49, 1, '2013-08-19T17:03:50.250592Z', NULL, '2025-11-25T02:15:32.847277Z'),
(2065, 'kanji', '浸', '浸', 'In the event of a <radical>tsunami</radical>, <radical>Wolverine</radical>, your <radical>forehead</radical>, and a <radical>stool</radical> will all be <kanji>immersed</kanji> in it. You will become immersed in the tsunami after it hits because tsunamis are gigantic and bring a lot of water. Now you and your forehead are immersed in the tsunami along with Wolverine and a stool.', 'https://api.wanikani.com/v2/subjects/2065', 'https://www.wanikani.com/kanji/%E6%B5%B8', 49, 1, '2013-08-19T17:04:15.50769Z', NULL, '2025-10-01T06:10:01.452142Z'),
(2066, 'kanji', '淡', '淡', 'A <radical>tsunami</radical> and a couple <radical>fire</radical>s run into each other. They cancel each other out completely, and the remainder left behind is a <kanji>faint</kanji> remnant of what was once there.', 'https://api.wanikani.com/v2/subjects/2066', 'https://www.wanikani.com/kanji/%E6%B7%A1', 49, 1, '2013-08-19T17:04:47.056856Z', NULL, '2025-10-01T06:10:01.46317Z'),
(2067, 'kanji', '煮', '煮', 'If <radical>someone</radical> wants to <radical>boil</radical>, you let them <kanji>boil</kanji>!', 'https://api.wanikani.com/v2/subjects/2067', 'https://www.wanikani.com/kanji/%E7%85%AE', 49, 1, '2013-08-19T17:05:12.806775Z', NULL, '2026-02-04T06:24:21.947579Z'),
(2068, 'kanji', '覆', '覆', 'If a <radical>helicopter</radical> <radical>loiter</radical>s near a <radical>black hole</radical> then it''s going to <kanji>capsize</kanji>. I mean, yeah, it''s not a boat, but just look, that''s what''s happening! That helicopter is going down!
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(3000, 'vocabulary', '助言', '助言', 'When you <kanji>help</kanji> with what you <kanji>say</kanji>, you''re giving <vocabulary>advice</vocabulary>.
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(4001, 'vocabulary', '恋愛', '恋愛', 'When you have <kanji>romance</kanji> and <kanji>love</kanji> all in the same package. Well, that is <vocabulary>love</vocabulary>! Ah, love! This is the word used when talking about love, though. You don''t use this to say "I love you."', 'https://api.wanikani.com/v2/subjects/4001', 'https://www.wanikani.com/vocabulary/%E6%81%8B%E6%84%9B', 17, 1, '2012-10-30T22:20:04.790902Z', NULL, '2025-11-27T19:28:57.446613Z'),
(4002, 'vocabulary', '自愛', '自愛', 'If you <kanji>love</kanji> your <kanji>self</kanji> that is <vocabulary>self love</vocabulary>. You’ll mostly see this word as part of the set phrase ご自愛下さい, which is used in emails and the like to remind the recipients to be good to themselves. Other variations include ご自愛くださいませ, ご自愛を, and ご自愛のほどを.', 'https://api.wanikani.com/v2/subjects/4002', 'https://www.wanikani.com/vocabulary/%E8%87%AA%E6%84%9B', 17, 1, '2012-10-30T22:20:12.934452Z', NULL, '2025-11-27T19:28:57.446613Z'),
(4003, 'vocabulary', '性愛-4003', '性愛', '<kanji>Gender</kanji> <kanji>love</kanji> is that kind of love that has to do with gender parts. That''s <vocabulary>sexual love</vocabulary>.', 'https://api.wanikani.com/v2/subjects/4003', 'https://www.wanikani.com/vocabulary/%E6%80%A7%E6%84%9B-4003', 17, 1, '2012-10-30T22:20:18.939364Z', '2021-09-02T17:43:20.487954Z', '2025-11-27T19:28:57.446613Z'),
(4004, 'vocabulary', '愛知県', '愛知県', 'The <kanji>Love</kanji> <kanji>Know</kanji> <kanji>Prefecture</kanji>! I want to live here, because people must know love! Of course, we don''t call it that in English. You''ll have to know the reading of the kanji to know the reading of this prefecture, which is <vocabulary>Aichi Prefecture</vocabulary> (jump to the reading to figure this out).', 'https://api.wanikani.com/v2/subjects/4004', 'https://www.wanikani.com/vocabulary/%E6%84%9B%E7%9F%A5%E7%9C%8C', 17, 1, '2012-10-30T22:20:26.928276Z', NULL, '2025-11-27T19:28:57.446613Z'),
(4005, 'vocabulary', '敗れる', '敗れる', 'This word consists of kanji with hiragana attached. Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means <kanji>defeat</kanji>, so this means <vocabulary>to be defeated</vocabulary>, but also <vocabulary>to be unsuccessful</vocabulary>.', 'https://api.wanikani.com/v2/subjects/4005', 'https://www.wanikani.com/vocabulary/%E6%95%97%E3%82%8C%E3%82%8B', 17, 1, '2012-10-30T22:20:36.939829Z', NULL, '2025-06-11T05:32:39.426322Z'),
(4006, 'vocabulary', '失敗', '失敗', 'A <kanji>fault</kanji> and a <kanji>failure</kanji>, all in one. This must have been one big <vocabulary>failure</vocabulary> and <vocabulary>mistake</vocabulary> you''ve made.', 'https://api.wanikani.com/v2/subjects/4006', 'https://www.wanikani.com/vocabulary/%E5%A4%B1%E6%95%97', 17, 1, '2012-10-30T22:20:46.36866Z', NULL, '2025-06-11T05:32:39.450781Z'),
(4007, 'vocabulary', '勝敗', '勝敗', 'You have <kanji>win</kanji> and you have <kanji>defeat</kanji>. When you are talking about both in one word, you have <vocabulary>victory or defeat</vocabulary>.', 'https://api.wanikani.com/v2/subjects/4007', 'https://www.wanikani.com/vocabulary/%E5%8B%9D%E6%95%97', 17, 1, '2012-10-30T22:22:33.356251Z', NULL, '2025-06-11T05:32:39.473739Z'),
(4008, 'vocabulary', '敗者', '敗者', 'The <kanji>defeat</kanji>ed <kanji>someone</kanji> is the <vocabulary>loser</vocabulary> or <vocabulary>the defeated</vocabulary>.', 'https://api.wanikani.com/v2/subjects/4008', 'https://www.wanikani.com/vocabulary/%E6%95%97%E8%80%85', 17, 1, '2012-10-30T22:22:52.33257Z', NULL, '2026-02-04T06:25:49.820187Z'),
(4009, 'vocabulary', '是非', '是非', '<kanji>Absolutely</kanji> an <kanji>injustice</kanji>! We must <vocabulary>absolutely</vocabulary> punish the perpetrator, <vocabulary>by all means</vocabulary>. First, though, we should probably define <vocabulary>right and wrong</vocabulary>.
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(5001, 'vocabulary', '抜ける', '抜ける', 'Remember how 抜く means "to pull something out"? 抜ける describes something coming out of where it was, so it means <vocabulary>to come out</vocabulary> or <vocabulary>to fall out</vocabulary>. 
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(6001, 'vocabulary', '継ぐ', '継ぐ', 'Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means <kanji>inherit</kanji> and the verb vocab version is <vocabulary>to inherit</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6001', 'https://www.wanikani.com/vocabulary/%E7%B6%99%E3%81%90', 36, 1, '2013-05-03T16:46:47.661009Z', NULL, '2025-06-11T05:33:27.684531Z'),
(6002, 'vocabulary', '継承', '継承', 'I will <kanji>inherit</kanji> at your <kanji>consent</kanji>. It''s not just given straight to me at birth, though it kind of is. I get <vocabulary>succession</vocabulary>, but only if people say it''s okay.', 'https://api.wanikani.com/v2/subjects/6002', 'https://www.wanikani.com/vocabulary/%E7%B6%99%E6%89%BF', 36, 1, '2013-05-03T16:46:53.203061Z', NULL, '2025-06-11T05:33:27.69625Z'),
(6003, 'vocabulary', '維持', '維持', '<kanji>Maintain</kanji> what we have and put it on <kanji>hold</kanji>. We need to keep it up to date and fixed, so we need <vocabulary>maintenance</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6003', 'https://www.wanikani.com/vocabulary/%E7%B6%AD%E6%8C%81', 36, 1, '2013-05-03T16:47:03.517466Z', NULL, '2025-06-11T05:33:27.708741Z'),
(6004, 'vocabulary', '維新', '維新', 'We must <kanji>maintain</kanji> the <kanji>new</kanji> and get rid of the old. It''s time for a <vocabulary>restoration</vocabulary> of policy! This also refers to the <vocabulary>Meiji Restoration</vocabulary> too. In fact, it probably mostly refers to this, though you''ll learn a more full version of this later.', 'https://api.wanikani.com/v2/subjects/6004', 'https://www.wanikani.com/vocabulary/%E7%B6%AD%E6%96%B0', 36, 1, '2013-05-03T16:47:14.670358Z', NULL, '2025-06-11T05:33:27.7212Z'),
(6005, 'vocabulary', '舞台', '舞台', 'A <kanji>dance</kanji> <kanji>machine</kanji> isn''t really a machine... a 台 is a large machine thing counter, so in this case it''s talking about a stage. A dancing stage is a <vocabulary>stage</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6005', 'https://www.wanikani.com/vocabulary/%E8%88%9E%E5%8F%B0', 36, 1, '2013-05-03T16:47:19.665577Z', NULL, '2025-06-11T05:33:27.736935Z'),
(6006, 'vocabulary', '舞う', '舞う', 'Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means <kanji>dance</kanji> and the verb vocab version means <vocabulary>to dance</vocabulary>, as well as <vocabulary>to flutter</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6006', 'https://www.wanikani.com/vocabulary/%E8%88%9E%E3%81%86', 36, 1, '2013-05-03T16:47:28.278974Z', NULL, '2025-06-11T05:33:27.750922Z'),
(6007, 'vocabulary', '歌舞伎', '歌舞伎', 'A <kanji>song</kanji> <kanji>dance</kanji> <kanji>deed</kanji> is a deed you do that involves singing and dancing. This is the traditional form of stage deeds, known as <vocabulary>kabuki</vocabulary>. Watch it on YouTube if you want a taste.', 'https://api.wanikani.com/v2/subjects/6007', 'https://www.wanikani.com/vocabulary/%E6%AD%8C%E8%88%9E%E4%BC%8E', 36, 1, '2013-05-03T16:47:34.55898Z', NULL, '2025-11-11T23:03:31.014085Z'),
(6008, 'vocabulary', '舞踏', '舞踏', 'You <kanji>dance</kanji>, you <kanji>step</kanji>, you dance, you step. Good job! Now you''re doing <vocabulary>dancing</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6008', 'https://www.wanikani.com/vocabulary/%E8%88%9E%E8%B8%8F', 36, 1, '2013-05-03T16:47:40.863083Z', NULL, '2025-06-11T05:33:27.774847Z'),
(6009, 'vocabulary', '踏む', '踏む', 'Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means <kanji>step</kanji> and the verb vocab version is <vocabulary>to step on</vocabulary>. So, not quite "to step" like you might expect, but at least you''re stepping still, though it''s on something.', 'https://api.wanikani.com/v2/subjects/6009', 'https://www.wanikani.com/vocabulary/%E8%B8%8F%E3%82%80', 36, 1, '2013-05-03T16:47:46.170873Z', NULL, '2026-02-24T00:32:20.946378Z'),
(6010, 'vocabulary', '一般', '一般', '<kanji>One</kanji> <kanji>generally</kanji> does things... in <vocabulary>general</vocabulary>. It''s more <vocabulary>common</vocabulary> this way.', 'https://api.wanikani.com/v2/subjects/6010', 'https://www.wanikani.com/vocabulary/%E4%B8%80%E8%88%AC', 36, 1, '2013-05-03T16:47:57.516024Z', NULL, '2025-06-11T05:33:27.804629Z'),
(6011, 'vocabulary', '超〜', '超〜', 'This has the same meaning as the kanji. Stick this onto another word and you have "ultra _____."', 'https://api.wanikani.com/v2/subjects/6011', 'https://www.wanikani.com/vocabulary/%E8%B6%85%E3%80%9C', 36, 1, '2013-05-03T16:48:02.777157Z', NULL, '2025-06-11T05:33:27.816351Z'),
(6012, 'vocabulary', '超自然的', '超自然的', 'Something that is <kanji>ultra</kanji> natural (自然的) is <vocabulary>supernatural</vocabulary>. Too natural! Super!', 'https://api.wanikani.com/v2/subjects/6012', 'https://www.wanikani.com/vocabulary/%E8%B6%85%E8%87%AA%E7%84%B6%E7%9A%84', 36, 1, '2013-05-03T16:48:53.667578Z', NULL, '2025-06-11T05:33:27.827221Z'),
(6013, 'vocabulary', '超音速-6013', '超音速', 'A <kanji>super</kanji> <kanji>sound</kanji> that''s <kanji>fast</kanji> is <vocabulary>supersonic speed</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6013', 'https://www.wanikani.com/vocabulary/%E8%B6%85%E9%9F%B3%E9%80%9F-6013', 36, 1, '2013-05-03T16:49:02.218698Z', '2021-09-09T18:05:39.698933Z', '2025-06-11T05:33:27.839889Z'),
(6014, 'vocabulary', '超音波', '超音波', 'An <kanji>ultra</kanji> <kanji>sound</kanji> <kanji>wave</kanji> is an <vocabulary>ultrasonic wave</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6014', 'https://www.wanikani.com/vocabulary/%E8%B6%85%E9%9F%B3%E6%B3%A2', 36, 1, '2013-05-03T16:49:08.875085Z', NULL, '2026-03-29T18:11:56.943742Z'),
(6015, 'vocabulary', '頼む', '頼む', 'Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means <kanji>trust</kanji>, but the verb vocab version is <vocabulary>to ask for</vocabulary> or <vocabulary>to rely on</vocabulary> or <vocabulary>to request</vocabulary>. When you trust someone you can 頼む them, but only when you trust them. You put it in their hands. You trust them, after all.', 'https://api.wanikani.com/v2/subjects/6015', 'https://www.wanikani.com/vocabulary/%E9%A0%BC%E3%82%80', 36, 1, '2013-05-03T16:49:16.241281Z', NULL, '2026-02-26T05:52:09.716486Z'),
(6016, 'vocabulary', '信頼', '信頼', 'I <kanji>believe</kanji> I can <kanji>trust</kanji> you. That''s why I put so much <vocabulary>reliance</vocabulary> and <vocabulary>trust</vocabulary> on you to do well.', 'https://api.wanikani.com/v2/subjects/6016', 'https://www.wanikani.com/vocabulary/%E4%BF%A1%E9%A0%BC', 36, 1, '2013-05-03T16:49:22.002606Z', NULL, '2025-11-16T19:02:11.093561Z'),
(6017, 'vocabulary', '依頼', '依頼', 'I am <kanji>reliant</kanji> on you and I <kanji>trust</kanji> you. Therefore, I have a <vocabulary>request</vocabulary> for you that I''d like to <vocabulary>entrust</vocabulary> you with.', 'https://api.wanikani.com/v2/subjects/6017', 'https://www.wanikani.com/vocabulary/%E4%BE%9D%E9%A0%BC', 36, 1, '2013-05-03T16:49:27.834551Z', NULL, '2025-06-11T05:33:27.894334Z'),
(6018, 'vocabulary', '依存', '依存', 'Being <kanji>reliant</kanji> on something in order to <kanji>exist</kanji> is <vocabulary>dependence</vocabulary> or <vocabulary>reliance</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6018', 'https://www.wanikani.com/vocabulary/%E4%BE%9D%E5%AD%98', 36, 1, '2013-05-03T16:49:33.046794Z', NULL, '2025-06-11T05:33:27.918095Z'),
(6019, 'vocabulary', '馬鹿', '馬鹿', 'A <kanji>horse</kanji> <kanji>deer</kanji> is a <vocabulary>stupid</vocabulary> idea. You''re an <vocabulary>idiot</vocabulary> for thinking about it, really. It''s quite <vocabulary>dumb</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6019', 'https://www.wanikani.com/vocabulary/%E9%A6%AC%E9%B9%BF', 36, 1, '2013-05-03T16:49:43.515879Z', NULL, '2025-06-11T05:33:27.929356Z'),
(6020, 'vocabulary', '鹿児島県', '鹿児島県', 'The <kanji>deer</kanji> <kanji>child</kanji> <kanji>island</kanji> <kanji>prefecture</kanji> is <vocabulary>Kagoshima Prefecture</vocabulary>. ', 'https://api.wanikani.com/v2/subjects/6020', 'https://www.wanikani.com/vocabulary/%E9%B9%BF%E5%85%90%E5%B3%B6%E7%9C%8C', 36, 1, '2013-05-03T16:49:48.086918Z', NULL, '2025-11-11T01:25:07.757919Z'),
(6021, 'vocabulary', '鹿', '鹿', 'The kanji and the word are exactly the same. That means they share meanings as well.', 'https://api.wanikani.com/v2/subjects/6021', 'https://www.wanikani.com/vocabulary/%E9%B9%BF', 36, 1, '2013-05-03T16:50:00.159862Z', NULL, '2025-06-11T05:33:27.953427Z'),
(6022, 'vocabulary', '承諾', '承諾', 'You have my <kanji>consent</kanji> and <kanji>agreement</kanji>. This is my <vocabulary>consent</vocabulary>, <vocabulary>agreement</vocabulary>, or <vocabulary>acceptance</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6022', 'https://www.wanikani.com/vocabulary/%E6%89%BF%E8%AB%BE', 36, 1, '2013-05-03T16:50:04.837445Z', NULL, '2025-06-11T05:33:27.975881Z'),
(6023, 'vocabulary', '受諾', '受諾', 'I will <kanji>accept</kanji> and I have <kanji>agreement</kanji> in the matter. I have come to <vocabulary>acceptance</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6023', 'https://www.wanikani.com/vocabulary/%E5%8F%97%E8%AB%BE', 36, 1, '2013-05-03T16:50:10.002341Z', NULL, '2025-11-08T00:22:48.601574Z'),
(6024, 'vocabulary', '許諾', '許諾', 'I will <kanji>permit</kanji> this, and you have my <kanji>agreement</kanji>. Both of these things combine to be my <vocabulary>permission</vocabulary> and my <vocabulary>consent</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6024', 'https://www.wanikani.com/vocabulary/%E8%A8%B1%E8%AB%BE', 36, 1, '2013-05-03T16:50:14.981142Z', NULL, '2025-06-11T05:33:28.011946Z'),
(6025, 'vocabulary', '諾否', '諾否', 'Do we have <kanji>agreement</kanji> or <kanji>no</kanji>? Which is it? <vocabulary>consent or refusal</vocabulary>? <vocabulary>Yes or no</vocabulary>? Choose!', 'https://api.wanikani.com/v2/subjects/6025', 'https://www.wanikani.com/vocabulary/%E8%AB%BE%E5%90%A6', 36, 1, '2013-05-03T16:50:20.763845Z', NULL, '2025-06-11T05:33:28.026768Z'),
(6026, 'vocabulary', '象牙', '象牙', 'An <kanji>elephant</kanji> <kanji>tusk</kanji> is the material known as <vocabulary>ivory</vocabulary> (or just an <vocabulary>elephant tusk</vocabulary>).', 'https://api.wanikani.com/v2/subjects/6026', 'https://www.wanikani.com/vocabulary/%E8%B1%A1%E7%89%99', 36, 1, '2013-05-03T16:50:35.159388Z', NULL, '2025-06-11T05:33:28.040695Z'),
(6027, 'vocabulary', '牙', '牙', 'The kanji and the word are exactly the same. That means they share meanings as well.', 'https://api.wanikani.com/v2/subjects/6027', 'https://www.wanikani.com/vocabulary/%E7%89%99', 36, 1, '2013-05-03T16:50:43.032385Z', NULL, '2025-06-11T05:33:28.052239Z'),
(6028, 'vocabulary', '降参する', '降参する', '降参 is "surrender" so the verb version would be <vocabulary>to surrender</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6028', 'https://www.wanikani.com/vocabulary/%E9%99%8D%E5%8F%82%E3%81%99%E3%82%8B', 36, 1, '2013-05-03T16:50:52.497911Z', NULL, '2025-11-14T21:46:55.985219Z'),
(6029, 'vocabulary', '一人暮らし', '一人暮らし', 'If 暮らす is "to live" or "to live one''s life," then to live one''s life as 一人, means you are <vocabulary>living alone</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6029', 'https://www.wanikani.com/vocabulary/%E4%B8%80%E4%BA%BA%E6%9A%AE%E3%82%89%E3%81%97', 37, 1, '2013-05-03T17:25:10.155358Z', NULL, '2025-12-04T08:41:25.964816Z'),
(6030, 'vocabulary', '彼女', '彼女', 'A <kanji>he</kanji> <kanji>woman</kanji> is <vocabulary>she</vocabulary>. Also could mean <vocabulary>girlfriend</vocabulary>, depending on how it''s used.', 'https://api.wanikani.com/v2/subjects/6030', 'https://www.wanikani.com/vocabulary/%E5%BD%BC%E5%A5%B3', 13, 1, '2013-05-03T17:25:19.142409Z', NULL, '2025-06-11T05:33:28.108669Z'),
(6031, 'vocabulary', '恥知らず', '恥知らず', '恥 is a "disgrace." If you 知らず then you don''t know something. In this case, you don''t know disgrace, and a person who doesn''t know disgrace is a <vocabulary>shameless person</vocabulary>, because they don''t care what disgraces them and what doesn''t.', 'https://api.wanikani.com/v2/subjects/6031', 'https://www.wanikani.com/vocabulary/%E6%81%A5%E7%9F%A5%E3%82%89%E3%81%9A', 37, 1, '2013-05-03T17:25:25.598861Z', NULL, '2026-03-29T19:07:09.364336Z'),
(6032, 'vocabulary', '試験地獄', '試験地獄', 'An "examination hell" is the nickname given to the exams you have to take in Japan all at once. That''s why this is <vocabulary>exam hell</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6032', 'https://www.wanikani.com/vocabulary/%E8%A9%A6%E9%A8%93%E5%9C%B0%E7%8D%84', 37, 1, '2013-05-03T17:25:38.008771Z', NULL, '2025-06-11T05:33:28.136634Z'),
(6033, 'vocabulary', '船酔い', '船酔い', 'When you''re <kanji>boat</kanji> <kanji>drunk</kanji> you have <vocabulary>sea sickness</vocabulary>.', 'https://api.wanikani.com/v2/subjects/6033', 'https://www.wanikani.com/vocabulary/%E8%88%B9%E9%85%94%E3%81%84', 37, 1, '2013-05-03T17:25:45.081696Z', NULL, '2025-06-11T05:33:28.151855Z'),
(6034, 'vocabulary', '〜鍋', '〜鍋', 'Remember how 鍋 means "<kanji>cooking pot</kanji>"? This is the suffix version of that, so it means ____<vocabulary>hotpot</vocabulary> or ____<vocabulary>stew</vocabulary>. 
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(7001, 'vocabulary', '瞳', '瞳', 'The kanji and the word are exactly the same. That means they share meanings as well. Remember, this is the eyeball pupil.', 'https://api.wanikani.com/v2/subjects/7001', 'https://www.wanikani.com/vocabulary/%E7%9E%B3', 46, 1, '2013-08-02T22:13:42.204101Z', NULL, '2025-06-11T05:33:41.676245Z'),
(7002, 'vocabulary', '鍵', '鍵', 'The kanji and the word are exactly the same. That means they share meanings as well.', 'https://api.wanikani.com/v2/subjects/7002', 'https://www.wanikani.com/vocabulary/%E9%8D%B5', 46, 1, '2013-08-02T22:14:49.848652Z', NULL, '2025-06-11T05:33:41.688246Z'),
(7003, 'vocabulary', '零', '零', 'The kanji and the word are exactly the same. That means they share meanings as well.', 'https://api.wanikani.com/v2/subjects/7003', 'https://www.wanikani.com/vocabulary/%E9%9B%B6', 46, 1, '2013-08-02T22:14:55.886976Z', NULL, '2025-06-11T05:33:41.699332Z'),
(7004, 'vocabulary', '零下', '零下', '<kanji>Zero</kanji> <kanji>below</kanji> is <vocabulary>below zero</vocabulary>. <vocabulary>Sub zero</vocabulary>.', 'https://api.wanikani.com/v2/subjects/7004', 'https://www.wanikani.com/vocabulary/%E9%9B%B6%E4%B8%8B', 46, 1, '2013-08-02T22:15:01.501102Z', NULL, '2025-11-07T23:06:30.483389Z'),
(7005, 'vocabulary', '零時', '零時', '<kanji>Zero</kanji> <kanji>o''clock</kanji> is 0:00. That''s <vocabulary>midnight</vocabulary> or <vocabulary>twelve o''clock</vocabulary>.', 'https://api.wanikani.com/v2/subjects/7005', 'https://www.wanikani.com/vocabulary/%E9%9B%B6%E6%99%82', 46, 1, '2013-08-02T22:15:07.26941Z', NULL, '2025-06-11T05:33:41.721663Z'),
(7006, 'vocabulary', '零点', '零点', '<kanji>Zero</kanji> <kanji>point</kanji>s means you got <vocabulary>zero point</vocabulary>s. Could also refer to getting <vocabulary>zero marks</vocabulary> on your test.', 'https://api.wanikani.com/v2/subjects/7006', 'https://www.wanikani.com/vocabulary/%E9%9B%B6%E7%82%B9', 46, 1, '2013-08-02T22:15:16.66754Z', NULL, '2025-06-11T05:33:41.733448Z'),
(7007, 'vocabulary', '零す', '零す', 'Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means <kanji>zero</kanji>, but the verb vocab version means <vocabulary>to spill something</vocabulary> or <vocabulary>to drop something</vocabulary>. Think of it this way, if you spill something, eventually it will reach <kanji>zero</kanji>.', 'https://api.wanikani.com/v2/subjects/7007', 'https://www.wanikani.com/vocabulary/%E9%9B%B6%E3%81%99', 47, 1, '2013-08-02T22:15:24.956811Z', NULL, '2025-09-17T17:45:43.514914Z'),
(7008, 'vocabulary', '碁', '碁', 'The kanji and the word are exactly the same. That means they share meanings as well, so this is <vocabulary>go</vocabulary>, as in <vocabulary>the game of go</vocabulary>.
INSERT INTO subjects (id, object_type, slug, characters, meaning_mnemonic, wanikani_api_url, wanikani_document_url, level, spaced_repetition_system_id, created_at, hidden_at, data_updated_at) VALUES
(8002, 'vocabulary', '清浄', '清浄', '<kanji>Pure</kanji> <kanji>cleanse</kanji>d things are <vocabulary>pure</vocabulary> and <vocabulary>clean</vocabulary>.', 'https://api.wanikani.com/v2/subjects/8002', 'https://www.wanikani.com/vocabulary/%E6%B8%85%E6%B5%84', 53, 1, '2015-07-02T17:21:38.377685Z', NULL, '2025-06-11T05:33:58.743266Z'),
(8003, 'vocabulary', '洗浄', '洗浄', 'You <kanji>wash</kanji> something to <kanji>cleanse</kanji> it by doing the <vocabulary>washing</vocabulary> and <vocabulary>cleaning</vocabulary>. You have to do the washing if you really want to get all the dirt out and make your things clean.
